def is_https_enabled() -> bool:
    return HTTPS_RUNTIME_ENABLED


def format_web_url(ip: str, scheme: str) -> str:
    port = HTTPS_PORT if scheme == "https" else PORT
    needs_port = (scheme == "https" and port != 443) or (scheme == "http" and port != 80)
    suffix = f":{port}" if needs_port else ""
    return f"{scheme}://{ip}{suffix}/"


def with_rev(path: str) -> str:
    sep = "&" if "?" in path else "?"
    return f"{path}{sep}v={PAGE_REV}"


def _fetch_google_doc_pdf_bytes(google_doc_id: str, timeout: int = 30) -> bytes | None:
    if not google_doc_id or not google_doc_id.strip():
        return None
    try:
        export_url = f"https://docs.google.com/document/d/{google_doc_id}/export?format=pdf"
        with urlopen(export_url, timeout=timeout) as response:
            pdf_data = response.read()
        if not pdf_data.startswith(b"%PDF"):
            return None
        return pdf_data
    except Exception:
        return None


def _read_cached_pdf(cache_path: pathlib.Path) -> bytes | None:
    try:
        if cache_path.exists():
            return cache_path.read_bytes()
    except Exception:
        return None
    return None


def download_google_doc_pdf(google_doc_id: str, cache_path: pathlib.Path) -> bool:
    """Скачивает PDF с Google Docs и сохраняет в кэш. Возвращает True если успешно."""
    pdf_data = _fetch_google_doc_pdf_bytes(google_doc_id, timeout=30)
    if pdf_data is None:
        return False
    try:
        cache_path.parent.mkdir(parents=True, exist_ok=True)
        cache_path.write_bytes(pdf_data)
        return True
    except Exception:
        return False


def get_pdf_data(doc_id: str, prefer_cache: bool = True) -> bytes | None:
    """Получает PDF данные. По умолчанию сразу отдает кэш, а сеть используется только при отсутствии кэша."""
    if not doc_id:
        return None

    cache_path = PDF_CACHE_DIR / f"{doc_id}.pdf"

    if prefer_cache:
        cached = _read_cached_pdf(cache_path)
        if cached is not None:
            return cached

    if download_google_doc_pdf(doc_id, cache_path):
        downloaded = _read_cached_pdf(cache_path)
        if downloaded is not None:
            return downloaded

    if not prefer_cache:
        return None

    fallback = _read_cached_pdf(cache_path)
    if fallback is not None:
        return fallback

    return None


def _load_machine_id() -> bytes:
    for path in ("/etc/machine-id", "/var/lib/dbus/machine-id"):
        try:
            with open(path, "rb") as f:
                machine_id = f.read().strip()
            if machine_id:
                return machine_id
        except OSError:
            continue
    return b""


def _load_config_json_direct() -> dict[str, Any]:
    try:
        with open(CONFIG_JSON, "r", encoding="utf-8") as f:
            payload = json.load(f) or {}
        return payload if isinstance(payload, dict) else {}
    except Exception:
        return {}


def load_portal_auth_config() -> dict[str, str]:
    raw = _load_config_json_direct().get("portal_auth")
    source = raw if isinstance(raw, dict) else {}
    username = str(source.get("username") or PORTAL_USERNAME).strip() or PORTAL_USERNAME
    password_hash = str(source.get("password_hash") or "").strip()
    return {
        "username": username,
        "password_hash": password_hash,
    }


def load_engineer_auth_config() -> dict[str, Any]:
    raw = _load_config_json_direct().get("engineer_auth")
    source = raw if isinstance(raw, dict) else {}
    env_enabled = bool(PORTAL_ENGINEER_USERNAME and (PORTAL_ENGINEER_PASSWORD_HASH or PORTAL_ENGINEER_PASSWORD))
    username = str(source.get("username") or PORTAL_ENGINEER_USERNAME or DEFAULT_ENGINEER_USERNAME).strip() or DEFAULT_ENGINEER_USERNAME
    password_hash = str(source.get("password_hash") or PORTAL_ENGINEER_PASSWORD_HASH or "").strip()
    enabled = bool(source.get("enabled", env_enabled))
    return {
        "enabled": enabled,
        "username": username,
        "password_hash": password_hash,
        "env_password": PORTAL_ENGINEER_PASSWORD if PORTAL_ENGINEER_USERNAME and username == PORTAL_ENGINEER_USERNAME else "",
    }


def get_portal_username() -> str:
    return load_portal_auth_config()["username"]


def portal_auth_revision(role: str = "user") -> str:
    digest = hashlib.sha256()
    digest.update(b"bmi30-portal-auth-revision")
    if role == "engineer":
        auth = load_engineer_auth_config()
        digest.update(str(auth["enabled"]).encode("utf-8", errors="ignore"))
        digest.update(str(auth["username"]).encode("utf-8", errors="ignore"))
        digest.update(str(auth["password_hash"] or auth["env_password"]).encode("utf-8", errors="ignore"))
    else:
        auth = load_portal_auth_config()
        digest.update(auth["username"].encode("utf-8", errors="ignore"))
        digest.update((auth["password_hash"] or f"plain:{PORTAL_PASSWORD}").encode("utf-8", errors="ignore"))
    return digest.hexdigest()[:24]


def _build_portal_session_secret() -> bytes:
    configured_secret = os.getenv("BMI30_PORTAL_SESSION_SECRET", "").strip()
    if configured_secret:
        return configured_secret.encode("utf-8")

    digest = hashlib.sha256()
    digest.update(b"bmi30-portal-session")
    digest.update(_load_machine_id() or os.urandom(32))
    auth = load_portal_auth_config()
    digest.update(auth["username"].encode("utf-8", errors="ignore"))
    digest.update((auth["password_hash"] or PORTAL_PASSWORD).encode("utf-8", errors="ignore"))
    engineer_auth = load_engineer_auth_config()
    digest.update(str(engineer_auth["enabled"]).encode("utf-8", errors="ignore"))
    digest.update(str(engineer_auth["username"]).encode("utf-8", errors="ignore"))
    digest.update(str(engineer_auth["password_hash"] or engineer_auth["env_password"]).encode("utf-8", errors="ignore"))
    return digest.digest()


PORTAL_SESSION_SECRET = _build_portal_session_secret()


def _b64url_encode(data: bytes) -> str:
    return base64.urlsafe_b64encode(data).decode("ascii").rstrip("=")


def _b64url_decode(value: str) -> bytes:
    padding = "=" * (-len(value) % 4)
    return base64.urlsafe_b64decode(value + padding)


def _format_cookie_expires(expires_at: int) -> str:
    return dt.datetime.fromtimestamp(expires_at, tz=dt.timezone.utc).strftime("%a, %d %b %Y %H:%M:%S GMT")


def constant_time_equals(left: str, right: str) -> bool:
    return hmac.compare_digest(left.encode("utf-8"), right.encode("utf-8"))


def hash_portal_password(password: str, *, salt: bytes | None = None, iterations: int = PORTAL_PASSWORD_HASH_ITERATIONS) -> str:
    if salt is None:
        salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac("sha256", password.encode("utf-8"), salt, iterations)
    return f"pbkdf2_sha256${iterations}${_b64url_encode(salt)}${_b64url_encode(digest)}"


def verify_portal_password_hash(password: str, stored_hash: str) -> bool:
    try:
        algorithm, iteration_s, salt_b64, digest_b64 = stored_hash.split("$", 3)
        if algorithm != "pbkdf2_sha256":
            return False
        iterations = int(iteration_s)
        if iterations < 100_000:
            return False
        salt = _b64url_decode(salt_b64)
        expected_digest = _b64url_decode(digest_b64)
    except Exception:
        return False

    candidate_digest = hashlib.pbkdf2_hmac(
        "sha256",
        password.encode("utf-8"),
        salt,
        iterations,
        dklen=len(expected_digest),
    )
    return hmac.compare_digest(candidate_digest, expected_digest)


def verify_portal_user_password(username: str, password: str) -> bool:
    auth = load_portal_auth_config()
    if not constant_time_equals(username, auth["username"]):
        return False
    if auth["password_hash"]:
        return verify_portal_password_hash(password, auth["password_hash"])
    return constant_time_equals(password, PORTAL_PASSWORD)


def verify_engineer_password(username: str, password: str) -> bool:
    auth = load_engineer_auth_config()
    if not auth["enabled"] or not constant_time_equals(username, str(auth["username"])):
        return False
    if auth["password_hash"]:
        return verify_portal_password_hash(password, str(auth["password_hash"]))
    if auth["env_password"]:
        return constant_time_equals(password, str(auth["env_password"]))
    return False


def is_engineer_account_enabled() -> bool:
    auth = load_engineer_auth_config()
    return bool(auth["enabled"] and (auth["password_hash"] or auth["env_password"]))


def authenticate_portal_credentials(username: str, password: str) -> dict[str, str] | None:
    if verify_portal_user_password(username, password):
        return {"username": get_portal_username(), "role": "user"}

    if verify_engineer_password(username, password):
        return {"username": str(load_engineer_auth_config()["username"]), "role": "engineer"}

    return None


def create_portal_session_token(username: str, expires_at: int, role: str = "user") -> str:
    payload = json.dumps(
        {"u": username, "exp": expires_at, "r": role, "v": portal_auth_revision(role)},
        separators=(",", ":"),
        sort_keys=True,
    ).encode("utf-8")
    payload_b64 = _b64url_encode(payload)
    signature = hmac.new(PORTAL_SESSION_SECRET, payload_b64.encode("ascii"), hashlib.sha256).hexdigest()
    return f"{payload_b64}.{signature}"


def parse_portal_session_token(token: str) -> dict[str, Any] | None:
    if not token or len(token) > 1024 or "." not in token:
        return None

    payload_b64, signature = token.rsplit(".", 1)
    expected_signature = hmac.new(PORTAL_SESSION_SECRET, payload_b64.encode("ascii"), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(signature, expected_signature):
        return None

    try:
        payload = json.loads(_b64url_decode(payload_b64).decode("utf-8"))
    except Exception:
        return None

    if not isinstance(payload, dict):
        return None

    try:
        username = str(payload.get("u", ""))
        expires_at = int(payload.get("exp", 0))
        role = str(payload.get("r", "user"))
        revision = str(payload.get("v", ""))
    except (TypeError, ValueError):
        return None

    if role == "user":
        expected_username = get_portal_username()
    elif role == "engineer" and is_engineer_account_enabled():
        expected_username = str(load_engineer_auth_config()["username"])
    else:
        return None

    if username != expected_username or expires_at <= 0:
        return None
    if revision != portal_auth_revision(role):
        return None

    return {"u": username, "exp": expires_at, "r": role}


def build_portal_session_cookie(token: str, *, remember: bool, secure: bool) -> str:
    jar = SimpleCookie()
    jar[PORTAL_SESSION_COOKIE] = token
    morsel = jar[PORTAL_SESSION_COOKIE]
    morsel["path"] = "/"
    morsel["httponly"] = True
    morsel["samesite"] = "Lax"
    if secure:
        morsel["secure"] = True
    if remember:
        expires_at = int(time.time()) + PORTAL_SESSION_TTL_S
        morsel["max-age"] = str(PORTAL_SESSION_TTL_S)
        morsel["expires"] = _format_cookie_expires(expires_at)
    return morsel.OutputString()


def build_expired_portal_session_cookie(*, secure: bool) -> str:
    jar = SimpleCookie()
    jar[PORTAL_SESSION_COOKIE] = ""
    morsel = jar[PORTAL_SESSION_COOKIE]
    morsel["path"] = "/"
    morsel["httponly"] = True
    morsel["samesite"] = "Lax"
    if secure:
        morsel["secure"] = True
    morsel["max-age"] = "0"
    morsel["expires"] = "Thu, 01 Jan 1970 00:00:00 GMT"
    return morsel.OutputString()


def run_command(*args: str) -> str:
    try:
        proc = subprocess.run(args, check=False, capture_output=True, text=True)
    except Exception:
        return ""
    if proc.returncode != 0:
        return ""
    return proc.stdout.strip()


_ANSI_ESCAPE_RE = re.compile(r"\x1b(?:\[[0-?]*[ -/]*[@-~]|\][^\x07]*(?:\x07|\x1b\\))")
_BLUETOOTH_MAC_RE = re.compile(r"^[0-9A-F]{2}(?::[0-9A-F]{2}){5}$")
_BLUETOOTH_AUDIO_UUIDS = frozenset({"1108", "110A", "110B", "1112", "111E", "111F"})
_BLUETOOTH_MIC_UUIDS = frozenset({"1108", "111E"})
_BLUEZ_HFP_PROFILE_UUID = "0000111e-0000-1000-8000-00805f9b34fb"


def _clean_process_text(value: Any, limit: int = 64000) -> str:
    text_value = _ANSI_ESCAPE_RE.sub("", str(value or "")).replace("\x00", "")
    text_value = "\n".join(line.rstrip() for line in text_value.splitlines() if line.strip())
    return text_value[: max(0, int(limit))]


def _process_result(
    args: list[str] | tuple[str, ...],
    *,
    timeout: float = 8.0,
) -> tuple[bool, str, int]:
    try:
        proc = subprocess.run(
            [str(arg) for arg in args],
            check=False,
            capture_output=True,
            text=True,
            timeout=max(0.2, float(timeout)),
        )
    except FileNotFoundError:
        return False, f"Command not found: {args[0] if args else 'unknown'}", 127
    except subprocess.TimeoutExpired as exc:
        partial = _clean_process_text((exc.stdout or "") + "\n" + (exc.stderr or ""))
        return False, partial or "Command timed out.", 124
    except Exception as exc:
        return False, _clean_process_text(exc), 1
    output = _clean_process_text((proc.stdout or "") + "\n" + (proc.stderr or ""))
    failed_text = output.lower()
    ok = proc.returncode == 0 and "failed to " not in failed_text
    return ok, output, int(proc.returncode)


def _bluetoothctl_result(*args: str, timeout: float = 8.0) -> tuple[bool, str, int]:
    return _process_result([BLUETOOTHCTL_BIN, *args], timeout=timeout)


def _bluez_connect_profile(address: str, profile_uuid: str) -> tuple[bool, str, int]:
    """Ask BlueZ for one remote profile without assuming a particular hci index."""
    address_token = str(address or "").strip().upper().replace(":", "_")
    tree_ok, tree_output, tree_rc = _process_result(
        ["busctl", "tree", "org.bluez", "--list"], timeout=5.0
    )
    if not tree_ok:
        return False, tree_output, tree_rc
    suffix = f"/dev_{address_token}"
    device_path = next(
        (line.strip() for line in tree_output.splitlines() if line.strip().endswith(suffix)),
        "",
    )
    if not device_path:
        return False, "BlueZ device object is unavailable.", 1
    return _process_result(
        [
            "busctl", "call", "org.bluez", device_path,
            "org.bluez.Device1", "ConnectProfile", "s", str(profile_uuid),
        ],
        timeout=2.5,
    )


def _parse_yes_no(value: Any) -> bool:
    return str(value or "").strip().lower() in {"yes", "true", "on", "1"}


def _parse_bluetooth_fields(output: str) -> dict[str, str]:
    fields: dict[str, str] = {}
    for raw_line in str(output or "").splitlines():
        line = raw_line.strip()
        if ":" not in line:
            continue
        key, value = line.split(":", 1)
        key = key.strip()
        if key and key not in fields:
            fields[key] = value.strip()
    return fields


def _parse_bluetooth_controller(output: str) -> dict[str, Any]:
    cleaned = _clean_process_text(output, 12000)
    match = re.search(
        r"^Controller\s+([0-9A-Fa-f:]{17})(?:\s+(.+?))?(?:\s+\[default\])?$",
        cleaned,
        flags=re.MULTILINE,
    )
    fields = _parse_bluetooth_fields(cleaned)
    return {
        "available": bool(match),
        "address": match.group(1).upper() if match else "",
        "name": fields.get("Name") or ((match.group(2) or "").strip() if match else ""),
        "alias": fields.get("Alias", ""),
        "powered": _parse_yes_no(fields.get("Powered")),
        "discovering": _parse_yes_no(fields.get("Discovering")),
        "pairable": _parse_yes_no(fields.get("Pairable")),
    }


def _parse_bluetooth_device_lines(output: str) -> list[dict[str, str]]:
    devices: dict[str, dict[str, str]] = {}
    cleaned = _clean_process_text(output, 64000)
    for line in cleaned.splitlines():
        match = re.match(r"^Device\s+([0-9A-Fa-f:]{17})(?:\s+(.*))?$", line.strip())
        if not match:
            continue
        address = match.group(1).upper()
        devices[address] = {"address": address, "name": (match.group(2) or "").strip()}
    return list(devices.values())


def _uuid_short_code(value: str) -> str:
    match = re.search(r"0000([0-9a-fA-F]{4})-0000-1000-8000-00805f9b34fb", value)
    return match.group(1).upper() if match else ""


def _parse_bluetooth_device_info(output: str, fallback: dict[str, str] | None = None) -> dict[str, Any]:
    fallback = fallback or {}
    cleaned = _clean_process_text(output, 32000)
    header = re.search(r"^Device\s+([0-9A-Fa-f:]{17})(?:\s+\([^)]*\))?$", cleaned, flags=re.MULTILINE)
    fields = _parse_bluetooth_fields(cleaned)
    address = (header.group(1) if header else fallback.get("address", "")).upper()
    uuid_labels: list[str] = []
    uuid_codes: list[str] = []
    for raw_line in cleaned.splitlines():
        match = re.match(r"^\s*UUID:\s*(.*?)\s*\(([^)]+)\)\s*$", raw_line)
        if not match:
            continue
        uuid_labels.append(match.group(1).strip())
        short_code = _uuid_short_code(match.group(2))
        if short_code:
            uuid_codes.append(short_code)
    class_value = 0
    raw_class = fields.get("Class", "")
    if raw_class:
        try:
            class_value = int(raw_class, 0)
        except ValueError:
            class_value = 0
    icon = fields.get("Icon", "")
    class_known = bool(raw_class)
    class_is_audio = bool(class_value and (class_value & 0x1F00) == 0x0400)
    uuid_is_audio = bool(set(uuid_codes) & _BLUETOOTH_AUDIO_UUIDS)
    icon_is_audio = "audio" in icon.lower() or "headset" in icon.lower()
    hid_capable = bool(set(uuid_codes) & {"1812", "1124"}) or icon.lower().startswith(("input-keyboard", "input-mouse", "input-gaming", "input-tablet"))
    rssi: int | None = None
    try:
        rssi = int(fields.get("RSSI", ""))
    except ValueError:
        pass
    return {
        "address": address,
        "name": fields.get("Name") or fallback.get("name") or address or "Unknown device",
        "alias": fields.get("Alias") or fields.get("Name") or fallback.get("name") or "",
        "icon": icon,
        "paired": _parse_yes_no(fields.get("Paired")),
        "bonded": _parse_yes_no(fields.get("Bonded")),
        "trusted": _parse_yes_no(fields.get("Trusted")),
        "blocked": _parse_yes_no(fields.get("Blocked")),
        "connected": _parse_yes_no(fields.get("Connected")),
        "rssi": rssi,
        "uuids": uuid_labels,
        "uuid_codes": uuid_codes,
        "audio_known": bool(icon or class_known or uuid_codes),
        "audio_capable": bool(class_is_audio or uuid_is_audio or icon_is_audio),
        "hid_capable": hid_capable,
        "microphone_service": bool(set(uuid_codes) & _BLUETOOTH_MIC_UUIDS),
    }


def _pulse_runtime() -> tuple[int, str]:
    try:
        uid = int(pwd.getpwnam(BLUETOOTH_AUDIO_USER).pw_uid)
    except Exception:
        uid = int(getattr(os, "getuid", lambda: 1000)())
    return uid, f"/run/user/{uid}"


def _player_voice_recording_active() -> bool:
    _uid, runtime_dir = _pulse_runtime()
    path = BLUETOOTH_PLAYER_VOICE_ACTIVE_FILE or os.path.join(
        runtime_dir,
        "bmi30-player-voice-active.json",
    )
    try:
        with open(path, "r", encoding="utf-8") as handle:
            state = json.load(handle)
        pid = int((state or {}).get("pid", 0) or 0)
        started_at = float((state or {}).get("started_at", 0.0) or 0.0)
        expires_at = float((state or {}).get("expires_at", started_at + 3600.0) or 0.0)
        now = time.time()
        if pid <= 0 or started_at <= 0.0 or expires_at <= now or now - started_at > 3600.0:
            raise ValueError("stale player voice lock")
        os.kill(pid, 0)
        return True
    except ProcessLookupError:
        pass
    except PermissionError:
        return True
    except Exception:
        pass
    try:
        if os.path.exists(path):
            os.unlink(path)
    except Exception:
        pass
    return False


def _pulse_user_command(binary: str, *args: str) -> list[str]:
    uid, runtime_dir = _pulse_runtime()
    pulse_server = f"unix:{runtime_dir}/pulse/native"
    if int(getattr(os, "geteuid", lambda: 1)()) == 0:
        try:
            audio_home = pwd.getpwnam(BLUETOOTH_AUDIO_USER).pw_dir
        except Exception:
            audio_home = f"/home/{BLUETOOTH_AUDIO_USER}"
        pulse_cookie = os.getenv(
            "BMI30_BLUETOOTH_AUDIO_COOKIE",
            os.path.join(audio_home, ".config", "pulse", "cookie"),
        )
        command = [
            "env",
            f"XDG_RUNTIME_DIR={runtime_dir}", f"PULSE_SERVER={pulse_server}",
            f"PULSE_COOKIE={pulse_cookie}",
            binary, *args,
        ]
    else:
        command = [
            "env", f"XDG_RUNTIME_DIR={runtime_dir}", f"PULSE_SERVER={pulse_server}",
            binary, *args,
        ]
    return command


def _pulse_user_result(binary: str, *args: str, timeout: float = 8.0) -> tuple[bool, str, int]:
    return _process_result(_pulse_user_command(binary, *args), timeout=timeout)


def _pactl_result(*args: str, timeout: float = 8.0) -> tuple[bool, str, int]:
    return _pulse_user_result("pactl", *args, timeout=timeout)


def _paplay_result(*args: str, timeout: float = 8.0) -> tuple[bool, str, int]:
    return _pulse_user_result("paplay", *args, timeout=timeout)


def _bluetooth_address_from_card_name(card_name: str) -> str:
    match = re.search(r"([0-9A-Fa-f]{2}(?:_[0-9A-Fa-f]{2}){5})", str(card_name or ""))
    return match.group(1).replace("_", ":").upper() if match else ""


def _parse_pulse_cards(output: str) -> list[dict[str, Any]]:
    cards: list[dict[str, Any]] = []
    blocks = re.split(r"(?=^Card #\d+\s*$)", str(output or ""), flags=re.MULTILINE)
    for block in blocks:
        if not block.startswith("Card #"):
            continue
        name_match = re.search(r"^\s*Name:\s*(\S+)\s*$", block, flags=re.MULTILINE)
        if not name_match:
            continue
        card_name = name_match.group(1).strip()
        address = _bluetooth_address_from_card_name(card_name)
        if not address:
            device_string = re.search(r'^\s*device\.string\s*=\s*"([0-9A-Fa-f:]{17})"\s*$', block, flags=re.MULTILINE)
            address = device_string.group(1).upper() if device_string else ""
        description_match = re.search(r'^\s*device\.description\s*=\s*"(.*?)"\s*$', block, flags=re.MULTILINE)
        active_match = re.search(r"^\s*Active Profile:\s*(\S+)\s*$", block, flags=re.MULTILINE)
        profiles: list[dict[str, Any]] = []
        profile_block = re.search(
            r"^\s*Profiles:\s*$([\s\S]*?)(?=^\s*Active Profile:|\Z)",
            block,
            flags=re.MULTILINE,
        )
        if profile_block:
            for raw_line in profile_block.group(1).splitlines():
                match = re.match(r"^\s+([A-Za-z0-9_.+-]+):\s*(.*?)\s*$", raw_line)
                if not match:
                    continue
                details = match.group(2).strip()
                available_match = re.search(r"\bavailable:\s*([^),\s]+)", details, flags=re.IGNORECASE)
                profiles.append({
                    "name": match.group(1),
                    "description": details,
                    "available": (available_match.group(1).strip().lower() if available_match else "unknown"),
                })
        cards.append({
            "name": card_name,
            "address": address,
            "description": description_match.group(1) if description_match else "",
            "active_profile": active_match.group(1) if active_match else "",
            "profiles": profiles,
        })
    return cards


def _pulse_audio_state() -> dict[str, Any]:
    ok, output, _returncode = _pactl_result("list", "cards", timeout=5.0)
    cards = _parse_pulse_cards(output) if ok else []
    return {
        "ready": bool(ok),
        "user": BLUETOOTH_AUDIO_USER,
        "cards": cards,
        "message": "" if ok else (output or "The PulseAudio-compatible desktop audio server is unavailable."),
    }


def _pulse_profile_is_microphone(name: str) -> bool:
    value = str(name or "").lower()
    return any(token in value for token in ("headset", "handsfree", "hfp_hf", "hsp_hs"))


def _pulse_profile_is_a2dp(name: str) -> bool:
    value = str(name or "").lower().replace("_", "-")
    return value.startswith("a2dp-")


def _pulse_profile_is_wideband(profile: dict[str, Any]) -> bool:
    name = str(profile.get("name") or "").lower()
    description = str(profile.get("description") or "").lower()
    if "cvsd" in name or "cvsd" in description:
        return False
    return "msbc" in name or "msbc" in description or name == "headset-head-unit"


def _pulse_card_requires_stable_cvsd(card: dict[str, Any]) -> bool:
    """Use CVSD for headsets whose mSBC stream is known to lose frames."""
    description = str(card.get("description") or "").strip().lower()
    address = str(card.get("address") or "").strip().upper()
    return "xp6" in description or address == "AF:51:80:97:7A:C0"


def _normalize_bluetooth_audio_config(raw: Any) -> dict[str, Any]:
    source = raw if isinstance(raw, dict) else {}
    devices_raw = source.get("devices") if isinstance(source.get("devices"), dict) else {}
    devices: dict[str, dict[str, Any]] = {}
    for raw_address, raw_settings in devices_raw.items():
        address = str(raw_address or "").strip().upper()
        if not _BLUETOOTH_MAC_RE.fullmatch(address):
            continue
        settings = raw_settings if isinstance(raw_settings, dict) else {}
        preferred_profile = str(settings.get("preferred_profile") or "").strip().lower()
        if preferred_profile not in {"microphone", "high_quality"}:
            preferred_profile = ""
        devices[address] = {
            "name": str(settings.get("name") or "")[:120],
            "auto_reconnect": bool(settings.get("auto_reconnect", True)),
            "preferred_profile": preferred_profile,
        }
    try:
        cue_volume = float(source.get("cue_volume_percent", BLUETOOTH_CONNECTION_CUE_VOLUME))
    except Exception:
        cue_volume = float(BLUETOOTH_CONNECTION_CUE_VOLUME)
    try:
        heartbeat_interval = float(source.get("heartbeat_interval_s", 1.0))
    except Exception:
        heartbeat_interval = 1.0
    return {
        "adapter_power": bool(source.get("adapter_power", True)),
        "auto_reconnect": bool(source.get("auto_reconnect", True)),
        "connection_cue": bool(source.get("connection_cue", True)),
        "connection_heartbeat": bool(source.get("connection_heartbeat", True)),
        "cue_volume_percent": max(1.0, min(100.0, cue_volume)),
        "heartbeat_interval_s": max(1.0, min(30.0, heartbeat_interval)),
        "devices": devices,
    }


def load_bluetooth_audio_config() -> dict[str, Any]:
    with _BLUETOOTH_CONFIG_LOCK:
        payload = _load_config_json()
        return _normalize_bluetooth_audio_config(payload.get("bluetooth_audio"))


def save_bluetooth_audio_config(cfg: dict[str, Any]) -> dict[str, Any]:
    normalized = _normalize_bluetooth_audio_config(cfg)
    with _BLUETOOTH_CONFIG_LOCK:
        payload = _load_config_json()
        payload["bluetooth_audio"] = normalized
        payload["bluetooth_audio_updated_at"] = int(time.time())
        _save_config_json(payload)
    return normalized


def _remember_bluetooth_audio_device(
    address: str,
    *,
    name: str = "",
    auto_reconnect: bool | None = None,
    preferred_profile: str | None = None,
) -> dict[str, Any]:
    address = str(address or "").strip().upper()
    if not _BLUETOOTH_MAC_RE.fullmatch(address):
        return load_bluetooth_audio_config()
    cfg = load_bluetooth_audio_config()
    devices = dict(cfg.get("devices") or {})
    current = dict(devices.get(address) or {})
    if name:
        current["name"] = str(name)[:120]
    if auto_reconnect is not None:
        current["auto_reconnect"] = bool(auto_reconnect)
    else:
        current.setdefault("auto_reconnect", True)
    if preferred_profile is not None:
        selected = str(preferred_profile or "").strip().lower()
        current["preferred_profile"] = selected if selected in {"microphone", "high_quality"} else ""
    devices[address] = current
    cfg["devices"] = devices
    return save_bluetooth_audio_config(cfg)


def _forget_bluetooth_audio_device(address: str) -> dict[str, Any]:
    address = str(address or "").strip().upper()
    cfg = load_bluetooth_audio_config()
    devices = dict(cfg.get("devices") or {})
    devices.pop(address, None)
    cfg["devices"] = devices
    return save_bluetooth_audio_config(cfg)


def _bluetooth_monitor_snapshot() -> dict[str, Any]:
    with _BLUETOOTH_MONITOR_LOCK:
        state = dict(_BLUETOOTH_MONITOR_STATE)
        attempts = dict(state.get("attempts") or {})
        state["attempt_count"] = len(attempts)
        state.pop("attempts", None)
        state.pop("suppress_until", None)
        state.pop("last_cue_at", None)
    return state


def _pulse_endpoint_for_address(address: str, kind: str) -> str:
    endpoint_kind = "sources" if kind == "source" else "sinks"
    expected_names = (
        ("bluez_input", "bluez_source")
        if kind == "source"
        else ("bluez_output", "bluez_sink")
    )
    ok, output, _returncode = _pactl_result("list", "short", endpoint_kind, timeout=5.0)
    if not ok:
        return ""
    address_token = str(address or "").replace(":", "_").lower()
    for line in output.splitlines():
        parts = line.split()
        if len(parts) < 2:
            continue
        endpoint_name = parts[1]
        endpoint_lower = endpoint_name.lower()
        if any(prefix in endpoint_lower for prefix in expected_names) and address_token in endpoint_lower:
            return endpoint_name
    return ""


def _pulse_default_source() -> str:
    ok, output, _returncode = _pactl_result("info", timeout=5.0)
    if not ok:
        return ""
    match = re.search(r"^Default Source:\s*(\S+)\s*$", output, flags=re.MULTILINE)
    return match.group(1) if match else ""


def _pcm_s16le_microphone_level(payload: bytes) -> tuple[float, float, float]:
    """Return RMS dBFS, display level, and peak level for signed 16-bit PCM."""
    usable = len(payload) - (len(payload) % 2)
    if usable <= 0:
        return -100.0, 0.0, 0.0
    square_sum = 0.0
    peak = 0
    sample_count = 0
    for (sample,) in struct.iter_unpack("<h", payload[:usable]):
        absolute = abs(int(sample))
        peak = max(peak, absolute)
        square_sum += float(sample) * float(sample)
        sample_count += 1
    rms = math.sqrt(square_sum / max(1, sample_count)) / 32768.0
    peak_normalized = float(peak) / 32768.0
    db = max(-100.0, min(0.0, 20.0 * math.log10(max(rms, 0.00001))))
    level_percent = max(0.0, min(100.0, ((db + 90.0) / 70.0) * 100.0))
    peak_db = max(-100.0, min(0.0, 20.0 * math.log10(max(peak_normalized, 0.00001))))
    peak_percent = max(0.0, min(100.0, ((peak_db + 90.0) / 70.0) * 100.0))
    return db, level_percent, peak_percent


def _bluetooth_microphone_meter_capture_command(source: str) -> list[str]:
    return _pulse_user_command(
        "parec",
        f"--device={source}",
        "--format=s16le",
        "--rate=8000",
        "--channels=1",
        "--latency-msec=80",
        "--process-time-msec=40",
        "--client-name=BMI30 Portal Microphone Meter",
        "--raw",
    )


def _bluetooth_microphone_meter_snapshot(*, refresh_lease: bool = False) -> dict[str, Any]:
    now = time.monotonic()
    with _BLUETOOTH_MIC_METER_LOCK:
        if refresh_lease and _BLUETOOTH_MIC_METER_STATE.get("enabled"):
            _BLUETOOTH_MIC_METER_STATE["requested_until"] = now + BLUETOOTH_MIC_METER_LEASE_S
        state = dict(_BLUETOOTH_MIC_METER_STATE)
    sample_age = now - float(state.get("last_sample_at", 0.0) or 0.0)
    if sample_age > 1.5:
        state["level_percent"] = 0.0
        state["peak_percent"] = 0.0
        state["db"] = -100.0
    state.pop("requested_until", None)
    state.pop("generation", None)
    state["sample_age_s"] = max(0.0, sample_age) if state.get("last_sample_at") else None
    state["capture"] = "raspberry-pulseaudio"
    return state


def _stop_bluetooth_microphone_meter(message: str = "Microphone meter stopped.") -> dict[str, Any]:
    global _BLUETOOTH_MIC_METER_PROCESS
    with _BLUETOOTH_MIC_METER_LOCK:
        _BLUETOOTH_MIC_METER_STATE["generation"] = int(
            _BLUETOOTH_MIC_METER_STATE.get("generation", 0)
        ) + 1
        _BLUETOOTH_MIC_METER_STATE.update({
            "enabled": False,
            "running": False,
            "level_percent": 0.0,
            "peak_percent": 0.0,
            "db": -100.0,
            "requested_until": 0.0,
            "message": message,
            "error": "",
        })
        process = _BLUETOOTH_MIC_METER_PROCESS
        _BLUETOOTH_MIC_METER_PROCESS = None
    if process is not None and process.poll() is None:
        try:
            process.terminate()
        except Exception:
            pass
    return _bluetooth_microphone_meter_snapshot()


def _bluetooth_microphone_meter_worker(generation: int, address: str, source: str) -> None:
    global _BLUETOOTH_MIC_METER_PROCESS
    process: subprocess.Popen[bytes] | None = None
    paused_for_player = False
    try:
        process = subprocess.Popen(
            _bluetooth_microphone_meter_capture_command(source),
            stdin=subprocess.DEVNULL,
            stdout=subprocess.PIPE,
            stderr=subprocess.DEVNULL,
            bufsize=0,
        )
        if process.stdout is None:
            raise RuntimeError("PulseAudio capture did not provide an audio stream.")
        with _BLUETOOTH_MIC_METER_LOCK:
            if generation != int(_BLUETOOTH_MIC_METER_STATE.get("generation", -1)):
                process.terminate()
                return
            _BLUETOOTH_MIC_METER_PROCESS = process
            _BLUETOOTH_MIC_METER_STATE.update({
                "running": True,
                "message": "Raspberry microphone capture is running.",
                "error": "",
            })
        descriptor = process.stdout.fileno()
        while process.poll() is None:
            if _player_voice_recording_active():
                paused_for_player = True
                break
            with _BLUETOOTH_MIC_METER_LOCK:
                if generation != int(_BLUETOOTH_MIC_METER_STATE.get("generation", -1)):
                    break
                requested_until = float(_BLUETOOTH_MIC_METER_STATE.get("requested_until", 0.0) or 0.0)
            if time.monotonic() >= requested_until:
                break
            readable, _writable, _exceptional = select.select([descriptor], [], [], 0.3)
            if not readable:
                continue
            chunk = os.read(descriptor, 4096)
            if not chunk:
                break
            db, level_percent, peak_percent = _pcm_s16le_microphone_level(chunk)
            with _BLUETOOTH_MIC_METER_LOCK:
                if generation != int(_BLUETOOTH_MIC_METER_STATE.get("generation", -1)):
                    break
                previous = float(_BLUETOOTH_MIC_METER_STATE.get("level_percent", 0.0) or 0.0)
                factor = 0.58 if level_percent > previous else 0.16
                smoothed = previous + (level_percent - previous) * factor
                _BLUETOOTH_MIC_METER_STATE.update({
                    "running": True,
                    "level_percent": smoothed,
                    "peak_percent": peak_percent,
                    "db": db,
                    "last_sample_at": time.monotonic(),
                    "message": "Raspberry microphone capture is running.",
                    "error": "",
                })
    except Exception as exc:
        with _BLUETOOTH_MIC_METER_LOCK:
            if generation == int(_BLUETOOTH_MIC_METER_STATE.get("generation", -1)):
                _BLUETOOTH_MIC_METER_STATE.update({
                    "running": False,
                    "message": "Microphone capture failed.",
                    "error": _clean_process_text(exc, 500),
                })
    finally:
        if process is not None and process.poll() is None:
            try:
                process.terminate()
                process.wait(timeout=1.0)
            except Exception:
                try:
                    process.kill()
                except Exception:
                    pass
        with _BLUETOOTH_MIC_METER_LOCK:
            if _BLUETOOTH_MIC_METER_PROCESS is process:
                _BLUETOOTH_MIC_METER_PROCESS = None
            if generation == int(_BLUETOOTH_MIC_METER_STATE.get("generation", -1)):
                _BLUETOOTH_MIC_METER_STATE.update({
                    "enabled": False,
                    "running": False,
                    "level_percent": 0.0,
                    "peak_percent": 0.0,
                    "db": -100.0,
                    "message": (
                        "Microphone meter paused while Player audio is active."
                        if paused_for_player
                        else "Microphone meter stopped because no browser was viewing it."
                        if not _BLUETOOTH_MIC_METER_STATE.get("error")
                        else _BLUETOOTH_MIC_METER_STATE.get("message")
                    ),
                })


def _start_bluetooth_microphone_meter(address: str) -> tuple[bool, str, dict[str, Any]]:
    address = str(address or "").strip().upper()
    if not _BLUETOOTH_MAC_RE.fullmatch(address):
        return False, "Invalid Bluetooth device address.", _bluetooth_microphone_meter_snapshot()
    if _player_voice_recording_active():
        return False, "Player audio is active; the separate meter is paused.", _bluetooth_microphone_meter_snapshot()
    with _BLUETOOTH_MIC_METER_LOCK:
        already_running = bool(
            _BLUETOOTH_MIC_METER_STATE.get("running")
            and _BLUETOOTH_MIC_METER_STATE.get("address") == address
        )
        if already_running:
            _BLUETOOTH_MIC_METER_STATE["enabled"] = True
            _BLUETOOTH_MIC_METER_STATE["requested_until"] = time.monotonic() + BLUETOOTH_MIC_METER_LEASE_S
            return True, "Raspberry microphone meter is already running.", _bluetooth_microphone_meter_snapshot()

    profile_ok, profile_message = apply_bluetooth_audio_action("microphone", address)
    if not profile_ok:
        return False, profile_message, _bluetooth_microphone_meter_snapshot()
    source = _pulse_endpoint_for_address(address, "source")
    if not source:
        return False, "The HFP/HSP profile is active, but its PulseAudio microphone source is unavailable.", _bluetooth_microphone_meter_snapshot()

    _stop_bluetooth_microphone_meter("Switching Raspberry microphone input.")
    with _BLUETOOTH_MIC_METER_LOCK:
        generation = int(_BLUETOOTH_MIC_METER_STATE.get("generation", 0)) + 1
        _BLUETOOTH_MIC_METER_STATE.update({
            "enabled": True,
            "running": False,
            "generation": generation,
            "address": address,
            "source": source,
            "level_percent": 0.0,
            "peak_percent": 0.0,
            "db": -100.0,
            "last_sample_at": 0.0,
            "requested_until": time.monotonic() + BLUETOOTH_MIC_METER_LEASE_S,
            "message": "Starting Raspberry microphone capture…",
            "error": "",
        })
    threading.Thread(
        target=_bluetooth_microphone_meter_worker,
        args=(generation, address, source),
        name="bmi30-bluetooth-microphone-meter",
        daemon=True,
    ).start()
    return True, profile_message, _bluetooth_microphone_meter_snapshot(refresh_lease=True)


def _play_bluetooth_connection_cue(address: str, *, force: bool = False) -> tuple[bool, str]:
    address = str(address or "").strip().upper()
    if _player_voice_recording_active():
        return True, "Bluetooth connection cue skipped while Player audio is active."
    cfg = load_bluetooth_audio_config()
    if not force and not bool(cfg.get("connection_cue", True)):
        return True, "Bluetooth connection cue is disabled."
    if not BLUETOOTH_CONNECTION_CUE_FILE or not os.path.isfile(BLUETOOTH_CONNECTION_CUE_FILE):
        return False, "Bluetooth connection cue file is unavailable."
    now = time.time()
    with _BLUETOOTH_MONITOR_LOCK:
        last_cue_at = float((_BLUETOOTH_MONITOR_STATE.get("last_cue_at") or {}).get(address, 0.0) or 0.0)
    if not force and now - last_cue_at < 15.0:
        return True, "Bluetooth connection cue was already played."
    sink_name = ""
    for _attempt in range(12):
        sink_name = _pulse_endpoint_for_address(address, "sink")
        if sink_name:
            break
        time.sleep(0.35)
    if not sink_name:
        return False, "Bluetooth audio sink did not appear; cue was not routed to another output."
    volume_percent = float(cfg.get("cue_volume_percent", BLUETOOTH_CONNECTION_CUE_VOLUME))
    pulse_volume = max(1, min(65536, int(round(65536.0 * volume_percent / 100.0))))
    if not _BLUETOOTH_PLAYBACK_LOCK.acquire(timeout=2.0):
        return False, "Bluetooth audio output is busy."
    try:
        ok, output, _returncode = _paplay_result(
            f"--device={sink_name}",
            f"--volume={pulse_volume}",
            BLUETOOTH_CONNECTION_CUE_FILE,
            timeout=8.0,
        )
    finally:
        _BLUETOOTH_PLAYBACK_LOCK.release()
    if ok:
        with _BLUETOOTH_MONITOR_LOCK:
            last_map = dict(_BLUETOOTH_MONITOR_STATE.get("last_cue_at") or {})
            last_map[address] = time.time()
            _BLUETOOTH_MONITOR_STATE["last_cue_at"] = last_map
        return True, f"Quiet connection cue played at {volume_percent:.0f}%."
    return False, output or "Unable to play Bluetooth connection cue."


def _play_bluetooth_heartbeat(address: str, *, force: bool = False) -> tuple[bool, str]:
    if _player_voice_recording_active():
        return True, "Bluetooth heartbeat skipped while Player audio is active."
    cfg = load_bluetooth_audio_config()
    if not force and not bool(cfg.get("connection_heartbeat", True)):
        return True, "Bluetooth heartbeat is disabled."
    if not BLUETOOTH_HEARTBEAT_CUE_FILE or not os.path.isfile(BLUETOOTH_HEARTBEAT_CUE_FILE):
        return False, "Bluetooth heartbeat sound file is unavailable."
    sink_name = _pulse_endpoint_for_address(address, "sink")
    if not sink_name:
        return False, "Bluetooth heartbeat sink is unavailable."
    volume_percent = float(cfg.get("cue_volume_percent", BLUETOOTH_CONNECTION_CUE_VOLUME))
    pulse_volume = max(1, min(65536, int(round(65536.0 * volume_percent / 100.0))))
    if not _BLUETOOTH_PLAYBACK_LOCK.acquire(blocking=force):
        return True, "Bluetooth heartbeat skipped while another headset sound is playing."
    try:
        ok, output, _returncode = _paplay_result(
            f"--device={sink_name}",
            f"--volume={pulse_volume}",
            BLUETOOTH_HEARTBEAT_CUE_FILE,
            timeout=3.0,
        )
    finally:
        _BLUETOOTH_PLAYBACK_LOCK.release()
    return (True, "Bluetooth heartbeat played.") if ok else (False, output or "Bluetooth heartbeat failed.")


def _play_bluetooth_test_sound(address: str) -> tuple[bool, str]:
    """Play one clearly audible sample without overlapping the heartbeat stream."""
    if _player_voice_recording_active():
        return False, "Test Sound is unavailable while Player audio is active."
    cfg = load_bluetooth_audio_config()
    if not BLUETOOTH_TEST_CUE_FILE or not os.path.isfile(BLUETOOTH_TEST_CUE_FILE):
        return False, "Bluetooth test sound file is unavailable."
    sink_name = _pulse_endpoint_for_address(address, "sink")
    if not sink_name:
        return False, "Bluetooth test-sound sink is unavailable."
    volume_percent = float(cfg.get("cue_volume_percent", BLUETOOTH_CONNECTION_CUE_VOLUME))
    pulse_volume = max(1, min(65536, int(round(65536.0 * volume_percent / 100.0))))
    if not _BLUETOOTH_PLAYBACK_LOCK.acquire(timeout=2.0):
        return False, "Bluetooth audio output is busy. Try the test again."
    try:
        ok, output, _returncode = _paplay_result(
            f"--device={sink_name}",
            f"--volume={pulse_volume}",
            BLUETOOTH_TEST_CUE_FILE,
            timeout=5.0,
        )
    finally:
        _BLUETOOTH_PLAYBACK_LOCK.release()
    if ok:
        return True, f"Bluetooth test sound played at {volume_percent:.0f}%."
    return False, output or "Bluetooth test sound failed."


def _scan_state_snapshot() -> dict[str, Any]:
    with _BLUETOOTH_SCAN_LOCK:
        state = dict(_BLUETOOTH_SCAN_STATE)
    state["remaining_s"] = max(0, int(round(float(state.get("ends_at", 0.0)) - time.time()))) if state.get("running") else 0
    return state


def _start_bluetooth_scan(duration_s: int | None = None) -> tuple[bool, str]:
    duration = max(5, min(60, int(duration_s or BLUETOOTH_SCAN_SECONDS)))
    with _BLUETOOTH_SCAN_LOCK:
        if _BLUETOOTH_SCAN_STATE.get("running"):
            return True, "Bluetooth scan is already running."
        generation = int(_BLUETOOTH_SCAN_STATE.get("generation", 0)) + 1
        _BLUETOOTH_SCAN_STATE.update({
            "running": True,
            "started_at": time.time(),
            "ends_at": time.time() + duration,
            "generation": generation,
            "last_message": "Scanning for nearby Bluetooth devices…",
        })

    def _worker() -> None:
        ok, output, _returncode = _bluetoothctl_result(
            "--timeout", str(duration), "scan", "on", timeout=float(duration + 6)
        )
        with _BLUETOOTH_SCAN_LOCK:
            if int(_BLUETOOTH_SCAN_STATE.get("generation", 0)) != generation:
                return
            _BLUETOOTH_SCAN_STATE["running"] = False
            _BLUETOOTH_SCAN_STATE["ends_at"] = time.time()
            _BLUETOOTH_SCAN_STATE["last_message"] = (
                "Bluetooth scan complete." if ok or "Discovery started" in output
                else (output or "Bluetooth scan failed.")
            )

    threading.Thread(target=_worker, name="bmi30-bluetooth-scan", daemon=True).start()
    return True, f"Scanning for Bluetooth devices for {duration} seconds."


def _stop_bluetooth_scan() -> tuple[bool, str]:
    ok, output, _returncode = _bluetoothctl_result("scan", "off", timeout=6.0)
    with _BLUETOOTH_SCAN_LOCK:
        _BLUETOOTH_SCAN_STATE["generation"] = int(_BLUETOOTH_SCAN_STATE.get("generation", 0)) + 1
        _BLUETOOTH_SCAN_STATE["running"] = False
        _BLUETOOTH_SCAN_STATE["ends_at"] = time.time()
        _BLUETOOTH_SCAN_STATE["last_message"] = "Bluetooth scan stopped." if ok else (output or "Unable to stop scan.")
    return ok, "Bluetooth scan stopped." if ok else (output or "Unable to stop Bluetooth scan.")


def _power_on_bluetooth() -> tuple[bool, str]:
    if int(getattr(os, "geteuid", lambda: 1)()) == 0:
        _process_result(["systemctl", "start", "bluetooth.service"], timeout=8.0)
        _process_result(["rfkill", "unblock", "bluetooth"], timeout=5.0)
    ok, output, _returncode = _bluetoothctl_result("power", "on", timeout=8.0)
    return ok, "Bluetooth adapter is on." if ok else (output or "Unable to power on Bluetooth adapter.")


def _power_off_bluetooth() -> tuple[bool, str]:
    ok, output, _returncode = _bluetoothctl_result("power", "off", timeout=8.0)
    return ok, "Bluetooth adapter is off." if ok else (output or "Unable to power off Bluetooth adapter.")


def _ensure_bluetooth_powered(desired_power: bool = True) -> tuple[bool, str]:
    show_ok, show_output, _returncode = _bluetoothctl_result("show", timeout=5.0)
    actual_power = bool(_parse_bluetooth_controller(show_output).get("powered")) if show_ok else False
    if actual_power == bool(desired_power):
        return True, "Bluetooth adapter power already matches the saved setting."
    return _power_on_bluetooth() if desired_power else _power_off_bluetooth()


def collect_bluetooth_audio_status() -> dict[str, Any]:
    controller_ok, controller_output, _controller_rc = _bluetoothctl_result("show", timeout=5.0)
    controller = _parse_bluetooth_controller(controller_output)
    if not controller.get("available") and controller_ok:
        controller["available"] = True
    devices_ok, devices_output, _devices_rc = _bluetoothctl_result("devices", timeout=5.0)
    base_devices = _parse_bluetooth_device_lines(devices_output) if devices_ok else []
    devices: list[dict[str, Any]] = []

    def _read_device(item: dict[str, str]) -> dict[str, Any]:
        info_ok, info_output, _info_rc = _bluetoothctl_result("info", item["address"], timeout=4.0)
        return _parse_bluetooth_device_info(info_output if info_ok else "", item)

    if base_devices:
        with ThreadPoolExecutor(max_workers=min(6, len(base_devices))) as pool:
            futures = [pool.submit(_read_device, item) for item in base_devices[:48]]
            for future in as_completed(futures):
                try:
                    devices.append(future.result())
                except Exception:
                    continue

    pulse = _pulse_audio_state()
    default_source = _pulse_default_source() if pulse.get("ready") else ""
    cards_by_address = {
        str(card.get("address") or "").upper(): card
        for card in pulse.get("cards", [])
        if card.get("address")
    }
    bluetooth_cfg = load_bluetooth_audio_config()
    configured_devices = bluetooth_cfg.get("devices") if isinstance(bluetooth_cfg.get("devices"), dict) else {}
    for device in devices:
        address = str(device.get("address") or "").upper()
        card = cards_by_address.get(address)
        if card:
            profiles = card.get("profiles") if isinstance(card.get("profiles"), list) else []
            device["audio_card"] = card
            device["microphone_profile_available"] = any(
                profile.get("available") != "no"
                and _pulse_profile_is_microphone(str(profile.get("name") or ""))
                for profile in profiles
            )
            device["high_quality_profile_available"] = any(
                profile.get("available") != "no" and _pulse_profile_is_a2dp(str(profile.get("name") or ""))
                for profile in profiles
            )
            device["audio_capable"] = True
            device["audio_known"] = True
            microphone_endpoint = _pulse_endpoint_for_address(address, "source")
            device["microphone_endpoint"] = microphone_endpoint
            device["microphone_ready"] = bool(microphone_endpoint)
            device["microphone_default"] = bool(
                microphone_endpoint and microphone_endpoint == default_source
            )
        else:
            device["audio_card"] = None
            device["microphone_profile_available"] = bool(device.get("microphone_service"))
            device["high_quality_profile_available"] = False
            device["microphone_endpoint"] = ""
            device["microphone_ready"] = False
            device["microphone_default"] = False
        saved_device = configured_devices.get(address) if isinstance(configured_devices.get(address), dict) else {}
        device["auto_reconnect"] = bool(saved_device.get("auto_reconnect", False))
        device["preferred_profile"] = str(saved_device.get("preferred_profile") or "")
    devices.sort(key=lambda item: (
        not bool(item.get("connected")),
        not bool(item.get("paired")),
        str(item.get("name") or "").lower(),
        str(item.get("address") or ""),
    ))
    scan = _scan_state_snapshot()
    controller["discovering"] = bool(controller.get("discovering") or scan.get("running"))
    return {
        "ok": bool(controller.get("available")),
        "controller": controller,
        "scan": scan,
        "devices": devices,
        "audio_server": {
            "ready": bool(pulse.get("ready")),
            "user": pulse.get("user", BLUETOOTH_AUDIO_USER),
            "message": pulse.get("message", ""),
            "default_source": default_source,
        },
        "settings": {
            "adapter_power": bool(bluetooth_cfg.get("adapter_power", True)),
            "auto_reconnect": bool(bluetooth_cfg.get("auto_reconnect", True)),
            "connection_cue": bool(bluetooth_cfg.get("connection_cue", True)),
            "connection_heartbeat": bool(bluetooth_cfg.get("connection_heartbeat", True)),
            "cue_volume_percent": float(bluetooth_cfg.get("cue_volume_percent", BLUETOOTH_CONNECTION_CUE_VOLUME)),
            "heartbeat_interval_s": float(bluetooth_cfg.get("heartbeat_interval_s", 1.0)),
        },
        "monitor": _bluetooth_monitor_snapshot(),
        "error": "" if controller.get("available") else (controller_output or "Bluetooth controller is unavailable."),
    }


def _select_bluetooth_audio_profile(address: str, *, microphone: bool, persist: bool = True) -> tuple[bool, str]:
    address = str(address or "").strip().upper()
    label = "HFP/HSP microphone" if microphone else "A2DP high-quality playback"
    if not _BLUETOOTH_PLAYBACK_LOCK.acquire(timeout=2.0):
        return False, "Bluetooth audio output is busy. Try again in a moment."
    try:
        deadline = time.monotonic() + 25.0
        profile_requested = False
        next_profile_attempt = 0.0
        last_message = "No PulseAudio card is available for this device. Connect it first, then refresh."
        selected_profile = ""
        while time.monotonic() < deadline:
            pulse = _pulse_audio_state()
            card = next(
                (item for item in pulse.get("cards", []) if str(item.get("address") or "").upper() == address),
                None,
            )
            if card:
                profiles = card.get("profiles") if isinstance(card.get("profiles"), list) else []
                matching: list[dict[str, Any]] = []
                for profile in profiles:
                    name = str(profile.get("name") or "")
                    lower = name.lower()
                    if microphone and _pulse_profile_is_microphone(lower):
                        matching.append(profile)
                    if not microphone and _pulse_profile_is_a2dp(lower):
                        matching.append(profile)
                if not matching:
                    return False, f"The connected device does not expose a {label} profile."
                candidates = [item for item in matching if item.get("available") != "no"] or matching
                if microphone:
                    stable_cvsd = _pulse_card_requires_stable_cvsd(card)
                    candidates.sort(key=lambda item: (
                        _pulse_profile_is_wideband(item) if stable_cvsd else not _pulse_profile_is_wideband(item),
                        str(item.get("name") or ""),
                    ))
                else:
                    candidates.sort(key=lambda item: ("ldac" not in str(item.get("name") or "").lower(), str(item.get("name") or "")))
                selected_profile = str(candidates[0].get("name") or "")
                active_profile = str(card.get("active_profile") or "").lower()
                active_matches = (
                    active_profile == selected_profile.lower()
                    if microphone else _pulse_profile_is_a2dp(active_profile)
                )
                if active_matches:
                    break
                if microphone and not profile_requested and not _pulse_profile_is_microphone(active_profile):
                    _bluez_connect_profile(address, _BLUEZ_HFP_PROFILE_UUID)
                    profile_requested = True
                now = time.monotonic()
                if now >= next_profile_attempt:
                    ok, output, _returncode = _pactl_result(
                        "set-card-profile", str(card.get("name") or ""), selected_profile, timeout=3.0
                    )
                    next_profile_attempt = time.monotonic() + 2.0
                    if ok:
                        break
                    last_message = output or "Unable to change the Bluetooth audio profile."
            elif microphone and not profile_requested:
                _bluez_connect_profile(address, _BLUEZ_HFP_PROFILE_UUID)
                profile_requested = True
            time.sleep(0.45)
        else:
            return False, f"Unable to enable {label}: {last_message}"

        endpoint_name = ""
        for _attempt in range(24):
            endpoint_name = _pulse_endpoint_for_address(
                address, "source" if microphone else "sink"
            )
            if endpoint_name:
                break
            time.sleep(0.25)
        if not endpoint_name:
            return False, f"The {label} profile was selected, but its audio endpoint did not appear."
        default_ok, default_output, _default_rc = _pactl_result(
            "set-default-source" if microphone else "set-default-sink",
            endpoint_name,
            timeout=5.0,
        )
        if not default_ok:
            return False, default_output or f"Unable to select the {label} endpoint."
        if persist:
            _remember_bluetooth_audio_device(
                address,
                auto_reconnect=True,
                preferred_profile="microphone" if microphone else "high_quality",
            )
        if microphone:
            wideband = selected_profile and _pulse_profile_is_wideband(
                next((item for item in candidates if str(item.get("name") or "") == selected_profile), {})
            )
            profile_label = (
                "wideband mSBC"
                if wideband
                else "stable CVSD 8 kHz (XP6 compatibility)"
                if _pulse_card_requires_stable_cvsd(card)
                else "narrowband CVSD"
            )
            return True, f"Voice microphone is ready for Raspberry capture ({profile_label}): {endpoint_name}."
        return True, "High-quality A2DP playback profile selected. The headset microphone is disabled in this mode."
    finally:
        _BLUETOOTH_PLAYBACK_LOCK.release()


def _read_bluetooth_device(address: str, name: str = "") -> dict[str, Any]:
    info_ok, info_output, _returncode = _bluetoothctl_result("info", address, timeout=5.0)
    return _parse_bluetooth_device_info(
        info_output if info_ok else "",
        {"address": address, "name": name},
    )


def _confirmed_bluetooth_audio_device(
    address: str,
    *,
    wait_for_profile: bool = False,
) -> tuple[bool, dict[str, Any]]:
    """Confirm an A2DP/HFP/HSP endpoint, never just a vendor-specific LE link."""
    attempts = 10 if wait_for_profile else 1
    latest: dict[str, Any] = {}
    for attempt in range(attempts):
        latest = _read_bluetooth_device(address)
        pulse = _pulse_audio_state()
        pulse_addresses = {
            str(card.get("address") or "").upper()
            for card in pulse.get("cards", [])
            if card.get("address")
        }
        if bool(latest.get("audio_capable") or address in pulse_addresses):
            return True, latest
        if attempt + 1 < attempts:
            time.sleep(0.45)
    return False, latest


def _restore_bluetooth_preferred_profile(address: str, preferred_profile: str) -> tuple[bool, str]:
    preferred_profile = str(preferred_profile or "").strip().lower()
    if preferred_profile not in {"microphone", "high_quality"}:
        return True, "Bluetooth audio profile left unchanged."
    last_message = "Bluetooth audio card is not ready."
    for _attempt in range(1):
        ok, message = _select_bluetooth_audio_profile(
            address,
            microphone=preferred_profile == "microphone",
            persist=False,
        )
        last_message = message
        if ok:
            return True, message
        if "No PulseAudio card" not in message:
            return False, message
        time.sleep(0.4)
    return False, last_message


def _bluetooth_audio_monitor_step(now: float | None = None) -> dict[str, Any]:
    current_time = float(now if now is not None else time.time())
    cfg = load_bluetooth_audio_config()
    configured = dict(cfg.get("devices") or {})
    devices_ok, devices_output, _devices_rc = _bluetoothctl_result("devices", timeout=5.0)
    base_devices = _parse_bluetooth_device_lines(devices_output) if devices_ok else []
    device_map: dict[str, dict[str, Any]] = {}
    for item in base_devices[:48]:
        address = str(item.get("address") or "").upper()
        if not address:
            continue
        device_map[address] = _read_bluetooth_device(address, str(item.get("name") or ""))
    for address, settings in configured.items():
        if address not in device_map:
            device_map[address] = _read_bluetooth_device(address, str((settings or {}).get("name") or ""))

    pulse = _pulse_audio_state()
    pulse_addresses = {
        str(card.get("address") or "").upper()
        for card in pulse.get("cards", [])
        if card.get("address")
    }
    connected_audio: set[str] = set()
    config_changed = False
    for address, device in device_map.items():
        is_audio = bool(device.get("audio_capable") or address in pulse_addresses)
        if not is_audio or not device.get("paired") or not device.get("trusted"):
            continue
        if device.get("connected"):
            connected_audio.add(address)
            if address not in configured:
                configured[address] = {
                    "name": str(device.get("name") or "")[:120],
                    "auto_reconnect": True,
                    "preferred_profile": "",
                }
                config_changed = True
    if config_changed:
        cfg["devices"] = configured
        cfg = save_bluetooth_audio_config(cfg)
        configured = dict(cfg.get("devices") or {})

    with _BLUETOOTH_MONITOR_LOCK:
        previous_connected = set(_BLUETOOTH_MONITOR_STATE.get("connected_audio") or [])
        attempts = dict(_BLUETOOTH_MONITOR_STATE.get("attempts") or {})
        suppress_until = dict(_BLUETOOTH_MONITOR_STATE.get("suppress_until") or {})

    for address in sorted(connected_audio - previous_connected):
        settings = configured.get(address) if isinstance(configured.get(address), dict) else {}
        preferred = str(settings.get("preferred_profile") or "")
        if preferred:
            _restore_bluetooth_preferred_profile(address, preferred)
        cue_ok, cue_message = _play_bluetooth_connection_cue(address)
        with _BLUETOOTH_MONITOR_LOCK:
            _BLUETOOTH_MONITOR_STATE["last_message"] = cue_message if cue_ok else f"Connected; {cue_message}"

    auto_global = bool(cfg.get("auto_reconnect", True))
    scan_running = bool(_scan_state_snapshot().get("running"))
    if auto_global and not scan_running:
        for address, settings_value in configured.items():
            settings = settings_value if isinstance(settings_value, dict) else {}
            if not bool(settings.get("auto_reconnect", True)):
                continue
            if current_time < float(suppress_until.get(address, 0.0) or 0.0):
                continue
            device = device_map.get(address) or _read_bluetooth_device(address, str(settings.get("name") or ""))
            if not device.get("paired") or not device.get("trusted"):
                continue
            if not bool(device.get("audio_capable") or address in pulse_addresses):
                continue
            if device.get("connected"):
                connected_audio.add(address)
                continue
            last_attempt = float(attempts.get(address, 0.0) or 0.0)
            if current_time - last_attempt < BLUETOOTH_RECONNECT_RETRY_S:
                continue
            attempts[address] = current_time
            if not _BLUETOOTH_ACTION_LOCK.acquire(blocking=False):
                continue
            try:
                ok, output, _returncode = _bluetoothctl_result(
                    "--timeout", "12", "connect", address, timeout=16.0
                )
            finally:
                _BLUETOOTH_ACTION_LOCK.release()
            if not ok:
                with _BLUETOOTH_MONITOR_LOCK:
                    _BLUETOOTH_MONITOR_STATE["last_message"] = output or f"Reconnect failed for {address}."
                continue
            connected_audio.add(address)
            preferred = str(settings.get("preferred_profile") or "")
            if preferred:
                _restore_bluetooth_preferred_profile(address, preferred)
            cue_ok, cue_message = _play_bluetooth_connection_cue(address)
            with _BLUETOOTH_MONITOR_LOCK:
                _BLUETOOTH_MONITOR_STATE["last_message"] = (
                    f"Reconnected {settings.get('name') or address}. {cue_message}"
                    if cue_ok else f"Reconnected {settings.get('name') or address}; {cue_message}"
                )

    with _BLUETOOTH_MONITOR_LOCK:
        _BLUETOOTH_MONITOR_STATE["last_check_at"] = current_time
        _BLUETOOTH_MONITOR_STATE["attempts"] = attempts
        _BLUETOOTH_MONITOR_STATE["connected_audio"] = sorted(connected_audio)
    return _bluetooth_monitor_snapshot()


def bluetooth_audio_monitor_background() -> None:
    with _BLUETOOTH_MONITOR_LOCK:
        _BLUETOOTH_MONITOR_STATE["running"] = True
    time.sleep(2.0)
    while True:
        try:
            cfg = load_bluetooth_audio_config()
            desired_power = bool(cfg.get("adapter_power", True))
            power_ok, power_message = _ensure_bluetooth_powered(desired_power)
            if not power_ok:
                with _BLUETOOTH_MONITOR_LOCK:
                    _BLUETOOTH_MONITOR_STATE["last_message"] = power_message
                time.sleep(BLUETOOTH_RECONNECT_POLL_S)
                continue
            if not desired_power:
                with _BLUETOOTH_MONITOR_LOCK:
                    _BLUETOOTH_MONITOR_STATE["connected_audio"] = []
                    _BLUETOOTH_MONITOR_STATE["last_message"] = "Bluetooth is off by saved user setting."
                time.sleep(BLUETOOTH_RECONNECT_POLL_S)
                continue
            _bluetooth_audio_monitor_step()
        except Exception as exc:
            message = _clean_process_text(exc, 400)
            with _BLUETOOTH_MONITOR_LOCK:
                _BLUETOOTH_MONITOR_STATE["last_message"] = message
            print(f"[BLUETOOTH-AUDIO] monitor error: {message}", flush=True)
        time.sleep(BLUETOOTH_RECONNECT_POLL_S)


def bluetooth_audio_heartbeat_background() -> None:
    next_tick = time.monotonic() + 1.0
    previous_interval = 1.0
    while True:
        cfg = load_bluetooth_audio_config()
        interval_s = max(1.0, min(30.0, float(cfg.get("heartbeat_interval_s", 1.0))))
        now = time.monotonic()
        if interval_s != previous_interval:
            next_tick = min(next_tick, now + interval_s)
            previous_interval = interval_s
        if now >= next_tick:
            while next_tick <= now:
                next_tick += interval_s
            if bool(cfg.get("connection_heartbeat", True)):
                with _BLUETOOTH_MONITOR_LOCK:
                    connected_audio = list(_BLUETOOTH_MONITOR_STATE.get("connected_audio") or [])
                for address in connected_audio:
                    _play_bluetooth_heartbeat(str(address))
        sleep_s = max(0.02, min(0.25, next_tick - time.monotonic()))
        time.sleep(sleep_s)


def apply_bluetooth_audio_action(action: str, address: str = "", value: Any = None) -> tuple[bool, str]:
    action = str(action or "").strip().lower()
    if action == "scan_start":
        ok, message = _power_on_bluetooth()
        if not ok:
            return False, message
        cfg = load_bluetooth_audio_config()
        cfg["adapter_power"] = True
        save_bluetooth_audio_config(cfg)
        return _start_bluetooth_scan()
    if action == "scan_stop":
        return _stop_bluetooth_scan()
    if action == "power_on":
        ok, message = _power_on_bluetooth()
        if ok:
            cfg = load_bluetooth_audio_config()
            cfg["adapter_power"] = True
            save_bluetooth_audio_config(cfg)
        return ok, message
    if action == "power_off":
        _stop_bluetooth_microphone_meter("Bluetooth power is off.")
        ok, message = _power_off_bluetooth()
        if ok:
            cfg = load_bluetooth_audio_config()
            cfg["adapter_power"] = False
            save_bluetooth_audio_config(cfg)
        return ok, message
    if action == "refresh":
        return True, "Bluetooth status refreshed."
    if action == "volume_set":
        try:
            volume_percent = float(value)
        except Exception:
            return False, "Invalid Bluetooth test-sound volume."
        cfg = load_bluetooth_audio_config()
        cfg["cue_volume_percent"] = max(1.0, min(100.0, volume_percent))
        cfg = save_bluetooth_audio_config(cfg)
        return True, f"Bluetooth test-sound volume saved at {cfg['cue_volume_percent']:.0f}%."
    if action == "heartbeat_test":
        cfg = load_bluetooth_audio_config()
        for saved_address in (cfg.get("devices") or {}):
            info = _read_bluetooth_device(str(saved_address))
            if info.get("connected") and info.get("audio_capable"):
                return _play_bluetooth_test_sound(str(saved_address))
        return False, "No connected Bluetooth audio headset is available for the test click."
    if action in {"cue_toggle", "heartbeat_toggle", "auto_global_toggle"}:
        cfg = load_bluetooth_audio_config()
        if action == "cue_toggle":
            cfg["connection_cue"] = not bool(cfg.get("connection_cue", True))
            cfg = save_bluetooth_audio_config(cfg)
            if cfg["connection_cue"]:
                return True, f"Headphone connection sound enabled at {cfg['cue_volume_percent']:.0f}%."
            return True, "Headphone connection sound disabled."
        if action == "heartbeat_toggle":
            cfg["connection_heartbeat"] = not bool(cfg.get("connection_heartbeat", True))
            cfg = save_bluetooth_audio_config(cfg)
            if cfg["connection_heartbeat"]:
                return True, f"Connected-headset heartbeat enabled every {cfg['heartbeat_interval_s']:.0f} second."
            return True, "Connected-headset heartbeat disabled."
        cfg["auto_reconnect"] = not bool(cfg.get("auto_reconnect", True))
        cfg = save_bluetooth_audio_config(cfg)
        return (
            True,
            "Automatic reconnect enabled for saved audio devices."
            if cfg["auto_reconnect"] else "Automatic reconnect disabled globally.",
        )
    address = str(address or "").strip().upper()
    if not _BLUETOOTH_MAC_RE.fullmatch(address):
        return False, "Invalid Bluetooth device address."
    if action not in {
        "pair", "connect", "disconnect", "remove", "microphone", "high_quality",
        "auto_on", "auto_off", "cue_test",
    }:
        return False, "Unsupported Bluetooth action."
    if not _BLUETOOTH_ACTION_LOCK.acquire(blocking=False):
        return False, "Another Bluetooth operation is still running."
    try:
        if action in {"disconnect", "remove", "high_quality"}:
            with _BLUETOOTH_MIC_METER_LOCK:
                meter_address = str(_BLUETOOTH_MIC_METER_STATE.get("address") or "").upper()
            if meter_address == address:
                _stop_bluetooth_microphone_meter("Bluetooth microphone profile is changing.")
        if action == "pair":
            power_ok, message = _power_on_bluetooth()
            if not power_ok:
                return False, message
            power_cfg = load_bluetooth_audio_config()
            power_cfg["adapter_power"] = True
            save_bluetooth_audio_config(power_cfg)
            info_ok, info_output, _info_rc = _bluetoothctl_result("info", address, timeout=5.0)
            info = _parse_bluetooth_device_info(info_output) if info_ok else {}
            if not info.get("paired"):
                ok, output, _returncode = _bluetoothctl_result(
                    "--agent", "NoInputNoOutput", "--timeout", "35", "pair", address, timeout=40.0
                )
                if not ok:
                    return False, output or "Bluetooth pairing failed. Put the device into pairing mode and try again."
            trust_ok, trust_output, _trust_rc = _bluetoothctl_result("trust", address, timeout=8.0)
            if not trust_ok:
                return False, trust_output or "Paired, but unable to trust the device."
            connect_ok, connect_output, _connect_rc = _bluetoothctl_result(
                "--timeout", "20", "connect", address, timeout=24.0
            )
            if not connect_ok:
                return False, connect_output or "Paired and trusted, but the connection failed."
            is_audio, connected_info = _confirmed_bluetooth_audio_device(address, wait_for_profile=True)
            if not is_audio:
                return False, (
                    "The device connected only as a non-audio/LE service. "
                    "Its A2DP or headset endpoint is not available, so automatic audio reconnect was not enabled."
                )
            _remember_bluetooth_audio_device(
                address,
                name=str(connected_info.get("name") or info.get("name") or ""),
                auto_reconnect=True,
            )
            cue_ok, cue_message = _play_bluetooth_connection_cue(address)
            suffix = cue_message if cue_ok else f"Connection sound skipped: {cue_message}"
            return True, f"Device paired, trusted, and connected. Automatic reconnect is enabled. {suffix}"
        if action == "connect":
            ok, output, _returncode = _bluetoothctl_result("--timeout", "20", "connect", address, timeout=24.0)
            if not ok:
                return False, output or "Bluetooth connection failed."
            power_cfg = load_bluetooth_audio_config()
            power_cfg["adapter_power"] = True
            save_bluetooth_audio_config(power_cfg)
            is_audio, connected_info = _confirmed_bluetooth_audio_device(address, wait_for_profile=True)
            if not is_audio:
                return False, (
                    "The device connected, but it exposes no A2DP/HFP/HSP audio service. "
                    "It will not be used for automatic audio reconnect."
                )
            _remember_bluetooth_audio_device(
                address,
                name=str(connected_info.get("name") or ""),
                auto_reconnect=True,
            )
            cue_ok, cue_message = _play_bluetooth_connection_cue(address)
            suffix = cue_message if cue_ok else f"Connection sound skipped: {cue_message}"
            return True, f"Bluetooth audio connected. Automatic reconnect is enabled. {suffix}"
        if action == "disconnect":
            ok, output, _returncode = _bluetoothctl_result("disconnect", address, timeout=12.0)
            if ok:
                with _BLUETOOTH_MONITOR_LOCK:
                    suppressed = dict(_BLUETOOTH_MONITOR_STATE.get("suppress_until") or {})
                    suppressed[address] = time.time() + 300.0
                    _BLUETOOTH_MONITOR_STATE["suppress_until"] = suppressed
            return (ok, "Bluetooth device disconnected." if ok else (output or "Bluetooth disconnect failed."))
        if action == "remove":
            ok, output, _returncode = _bluetoothctl_result("remove", address, timeout=12.0)
            if ok:
                _forget_bluetooth_audio_device(address)
            return (ok, "Bluetooth device removed from saved devices." if ok else (output or "Unable to remove Bluetooth device."))
        if action == "microphone":
            return _select_bluetooth_audio_profile(address, microphone=True)
        if action == "high_quality":
            return _select_bluetooth_audio_profile(address, microphone=False)
        is_audio, info = _confirmed_bluetooth_audio_device(address)
        if not bool(info.get("paired") and info.get("trusted")):
            return False, "Pair and trust this audio device before enabling automatic reconnect."
        if not is_audio:
            return False, "This saved link exposes no A2DP/HFP/HSP audio service; automatic reconnect was not enabled."
        if action == "auto_on":
            _remember_bluetooth_audio_device(
                address,
                name=str(info.get("name") or ""),
                auto_reconnect=True,
            )
            return True, "Automatic reconnect enabled for this audio device."
        if action == "auto_off":
            _remember_bluetooth_audio_device(
                address,
                name=str(info.get("name") or ""),
                auto_reconnect=False,
            )
            return True, "Automatic reconnect disabled for this audio device."
        if not info.get("connected"):
            return False, "Connect the audio device before testing its connection sound."
        return _play_bluetooth_test_sound(address)
    finally:
        _BLUETOOTH_ACTION_LOCK.release()


def _read_first_text(paths: tuple[str, ...]) -> str:
    for path in paths:
        try:
            with open(path, "r", encoding="utf-8", errors="replace") as f:
                value = f.read().replace("\x00", "").strip()
            if value:
                return value
        except Exception:
            continue
    return ""


# BMI30 hardware RPI identity, 2026-10-23
RPI_IDENTITY_VERSION = "2026-10-23"
_BMI30_HARDWARE_SERIAL = ""


def _bmi30_hardware_serial() -> str:
    """Read the current board, never a cloned hostname or removable medium."""
    global _BMI30_HARDWARE_SERIAL
    if _BMI30_HARDWARE_SERIAL:
        return _BMI30_HARDWARE_SERIAL
    for path in ("/proc/device-tree/serial-number",
                 "/sys/firmware/devicetree/base/serial-number", "/proc/cpuinfo"):
        try:
            with open(path, "r", encoding="utf-8") as stream:
                value = stream.read(262144)
        except (OSError, UnicodeError):
            continue
        if path == "/proc/cpuinfo":
            match = re.search(r"^Serial\s*:\s*([0-9A-Fa-f]{16})\s*$", value, re.MULTILINE)
            value = match.group(1) if match else ""
        else:
            value = value.strip("\x00 \t\r\n")
        if re.fullmatch(r"[0-9A-Fa-f]{16}", value) and int(value, 16):
            _BMI30_HARDWARE_SERIAL = value.upper()
            return _BMI30_HARDWARE_SERIAL
    return ""


def _bmi30_hardware_hostname() -> str:
    serial = _bmi30_hardware_serial()
    return "BMI30-" + serial[-9:] if serial else ""


def detect_rpi_identity() -> dict[str, str]:
    info = {"serial": "", "model": "", "revision": "", "software_version": ""}
    try:
        with open("/proc/cpuinfo", "r", encoding="utf-8", errors="replace") as f:
            for raw_line in f:
                if ":" not in raw_line:
                    continue
                key, value = raw_line.split(":", 1)
                key = key.strip().lower()
                value = value.strip()
                if key == "serial" and value:
                    info["serial"] = value
                elif key == "model" and value:
                    info["model"] = value
                elif key == "revision" and value:
                    info["revision"] = value
    except Exception:
        pass
    if not info["model"]:
        info["model"] = _read_first_text((
            "/sys/firmware/devicetree/base/model",
            "/proc/device-tree/model",
        ))
    info["serial"] = _bmi30_hardware_serial()
    info["software_version"] = detect_rpi_software_version()
    return info


def _read_key_value_file(path: str) -> dict[str, str]:
    data: dict[str, str] = {}
    try:
        with open(path, "r", encoding="utf-8", errors="replace") as f:
            for raw_line in f:
                line = raw_line.strip()
                if not line or line.startswith("#") or "=" not in line:
                    continue
                key, value = line.split("=", 1)
                value = value.strip()
                try:
                    parsed = shlex.split(value, comments=False, posix=True)
                    value = parsed[0] if len(parsed) == 1 else value.strip("'\"")
                except ValueError:
                    value = value.strip("'\"")
                data[key.strip()] = value
    except Exception:
        pass
    return data


def detect_bmi30_firmware_release() -> dict[str, Any]:
    manifest_path = ""
    data: dict[str, str] = {}
    for candidate in (
        os.getenv("BMI30_FIRMWARE_MANIFEST", "").strip(),
        "/home/techaid/Documents/host/bmi30_firmware_release.env",
        os.path.join(os.path.dirname(__file__), "host", "bmi30_firmware_release.env"),
        "/usr/local/bin/host/bmi30_firmware_release.env",
    ):
        if not candidate:
            continue
        candidate_data = _read_key_value_file(candidate)
        if candidate_data.get("BMI30_FIRMWARE_VERSION"):
            manifest_path = candidate
            data = candidate_data
            break

    version = data.get("BMI30_FIRMWARE_VERSION", "").strip()
    label = data.get("BMI30_FIRMWARE_LABEL", "").strip() or version
    expected_portal_hash = data.get("BMI30_FIRMWARE_PORTAL_SHA256", "").strip().lower()
    runtime_portal_hash = PORTAL_RUNTIME_SHA256.lower()
    portal_matches = bool(expected_portal_hash and runtime_portal_hash == expected_portal_hash)

    return {
        "version": version,
        "label": label,
        "created_at": data.get("BMI30_FIRMWARE_CREATED_AT", "").strip(),
        "content_signature": data.get("BMI30_FIRMWARE_CONTENT_SIGNATURE", "").strip(),
        "signature_version": data.get("BMI30_FIRMWARE_SIGNATURE_VERSION", "").strip(),
        "core_path": data.get("BMI30_FIRMWARE_CORE_PATH", "").strip(),
        "engine_path": data.get("BMI30_FIRMWARE_ENGINE_PATH", "").strip(),
        "gui_path": data.get("BMI30_FIRMWARE_GUI_PATH", "").strip(),
        "portal_path": data.get("BMI30_FIRMWARE_PORTAL_PATH", "").strip(),
        "portal_sha256": expected_portal_hash,
        "runtime_portal_sha256": runtime_portal_hash,
        "portal_matches_release": portal_matches,
        "manifest_path": manifest_path,
    }


def format_firmware_version_with_date(release: dict[str, Any]) -> str:
    """Return the dated release ID for compact FW displays, not its prose label."""
    version = str(release.get("version") or "").strip()
    match = re.match(r"^(\d{4}-\d{2}-\d{2}-\d{4})(?:[-_.]|$)", version)
    if match:
        return match.group(1)
    return version or str(release.get("label") or "").strip()


def _firmware_version_key(value: Any) -> tuple[int, int, int, int, int, int] | None:
    text = str(value or "").strip()
    match = re.search(
        r"(\d{4})-(\d{2})-(\d{2})[-_](\d{2})(\d{2})(\d{2})?",
        text,
    )
    if not match:
        return None
    try:
        return tuple(int(part or 0) for part in match.groups())  # type: ignore[return-value]
    except (TypeError, ValueError):
        return None


def _firmware_is_newer(remote_version: Any, current_version: Any) -> bool:
    remote_key = _firmware_version_key(remote_version)
    current_key = _firmware_version_key(current_version)
    return bool(remote_key and current_key and remote_key > current_key)


def _firmware_text(value: Any, limit: int = 600) -> str:
    return str(value or "").replace("\x00", "").strip()[:limit]


def _firmware_current_metadata() -> dict[str, Any]:
    release = detect_bmi30_firmware_release()
    split = detect_bmi30_split_system_version()
    active_data = _read_key_value_file(
        str(FIRMWARE_WORKSPACE / "host" / "bmi30_split_active_version.env")
    )
    return {
        "version": _firmware_text(release.get("version") or split.get("version"), 160),
        "label": _firmware_text(release.get("label") or split.get("label"), 300),
        "created_at": _firmware_text(release.get("created_at"), 120),
        "bundle_id": _firmware_text(active_data.get("BMI30_SPLIT_BUNDLE_ID"), 160),
        "content_signature": _firmware_text(release.get("content_signature"), 80),
    }


def _read_firmware_operation_state() -> dict[str, Any]:
    try:
        with FIRMWARE_OPERATION_FILE.open("r", encoding="utf-8") as handle:
            data = json.load(handle)
        if not isinstance(data, dict):
            raise ValueError("operation state is not an object")
    except Exception:
        return {
            "action": "",
            "status": "idle",
            "progress": 0,
            "message": "",
            "error": "",
            "updated_at": 0,
        }

    action = str(data.get("action") or "")
    status = str(data.get("status") or "idle")
    try:
        progress = max(0, min(100, int(data.get("progress") or 0)))
    except (TypeError, ValueError):
        progress = 0
    try:
        updated_at = int(data.get("updated_at") or 0)
    except (TypeError, ValueError):
        updated_at = 0
    if status in {"starting", "running"} and updated_at and (time.time() - updated_at) > 7200:
        status = "failed"
        data["error"] = "The firmware operation stopped reporting progress."
    return {
        "action": action if action in {"update", "rollback"} else "",
        "status": status,
        "progress": progress,
        "message": _firmware_text(data.get("message"), 240),
        "error": _firmware_text(data.get("error"), 500),
        "updated_at": updated_at,
    }


def _firmware_operation_busy() -> bool:
    return _read_firmware_operation_state().get("status") in {"starting", "running"}


def _read_firmware_rollback_state() -> dict[str, Any]:
    data = _read_key_value_file(str(FIRMWARE_ROLLBACK_FILE))
    available = str(data.get("ROLLBACK_AVAILABLE") or "").strip() == "1"
    bundle_id = _firmware_text(data.get("ROLLBACK_BUNDLE_ID"), 160)
    bundle_dir = FIRMWARE_WORKSPACE / "host" / "bmi30_split_bundles" / bundle_id
    available = bool(available and bundle_id and bundle_dir.is_dir())
    return {
        "available": available,
        "version": _firmware_text(
            data.get("ROLLBACK_FIRMWARE_VERSION") or data.get("ROLLBACK_BUNDLE_ID"),
            160,
        ),
        "bundle_id": bundle_id,
        "label": _firmware_text(data.get("ROLLBACK_LABEL"), 300),
        "notes": _firmware_text(data.get("ROLLBACK_NOTES"), 600),
        "created_at": _firmware_text(data.get("ROLLBACK_CREATED_AT"), 120),
        "saved_at": _firmware_text(data.get("ROLLBACK_SAVED_AT"), 120),
        "updated_to_version": _firmware_text(data.get("UPDATED_TO_VERSION"), 160),
        "updated_to_bundle": _firmware_text(data.get("UPDATED_TO_BUNDLE_ID"), 160),
    }


def _write_firmware_operation_state(
    action: str,
    status: str,
    progress: int,
    message: str,
    error: str = "",
) -> None:
    FIRMWARE_STATE_DIR.mkdir(parents=True, exist_ok=True)
    payload = {
        "action": action,
        "status": status,
        "progress": max(0, min(100, int(progress))),
        "message": message,
        "error": error,
        "updated_at": int(time.time()),
    }
    temporary = FIRMWARE_OPERATION_FILE.with_name(
        f".{FIRMWARE_OPERATION_FILE.name}.tmp.{os.getpid()}.{threading.get_ident()}"
    )
    with temporary.open("w", encoding="utf-8") as handle:
        json.dump(payload, handle, ensure_ascii=False, separators=(",", ":"))
        handle.write("\n")
    os.replace(temporary, FIRMWARE_OPERATION_FILE)


def check_firmware_update() -> dict[str, Any]:
    if _firmware_operation_busy():
        return {"ok": False, "busy": True, "error": "A firmware operation is running."}

    checked_at = int(time.time())
    with _FIRMWARE_CONTROL_LOCK:
        _FIRMWARE_CONTROL_STATE["checking"] = True
        _FIRMWARE_CONTROL_STATE["error"] = ""
    try:
        proc = subprocess.run(
            ["/usr/bin/python3", str(FIRMWARE_WORKSPACE / "utilities/bmi30_server_update.py"),
             "check", "--project", str(FIRMWARE_WORKSPACE)],
            capture_output=True, text=True, timeout=FIRMWARE_CHECK_TIMEOUT_S,
        )
        result = json.loads(proc.stdout)
        if proc.returncode or not result.get("ok"):
            raise RuntimeError(result.get("error", "Server firmware check failed"))
        cloud = result.get("cloud") or {}
        with _FIRMWARE_CONTROL_LOCK:
            _FIRMWARE_CONTROL_STATE.update({
                "checking": False, "checked_at": checked_at,
                "next_check_at": checked_at + FIRMWARE_CHECK_INTERVAL_S,
                "online": True, "available": bool(result.get("available")),
                "error": result.get("message", ""), "cloud": cloud,
            })
        return {"ok": True, "available": bool(result.get("available")), "cloud": cloud}
    except Exception as exc:
        with _FIRMWARE_CONTROL_LOCK:
            _FIRMWARE_CONTROL_STATE.update({
                "checking": False, "checked_at": checked_at,
                "next_check_at": checked_at + FIRMWARE_CHECK_INTERVAL_S,
                "online": False, "available": False, "cloud": {},
                "error": _firmware_text(exc, 500),
            })
        return {"ok": False, "error": _firmware_text(exc, 500)}


def firmware_control_public_state() -> dict[str, Any]:
    with _FIRMWARE_CONTROL_LOCK:
        cloud_state = json.loads(json.dumps(_FIRMWARE_CONTROL_STATE))
    current = _firmware_current_metadata()
    cloud = cloud_state.get("cloud") if isinstance(cloud_state.get("cloud"), dict) else {}
    available = bool(
        cloud
        and _firmware_is_newer(cloud.get("version"), current.get("version"))
        and cloud_state.get("available")
    )
    operation = _read_firmware_operation_state()
    rollback = _read_firmware_rollback_state()
    busy = operation.get("status") in {"starting", "running"}
    return {
        "ok": True,
        "current": current,
        "cloud": {
            **cloud,
            "available": bool(available and not busy),
            "checking": bool(cloud_state.get("checking")),
            "online": bool(cloud_state.get("online")),
            "checked_at": int(cloud_state.get("checked_at") or 0),
            "next_check_at": int(cloud_state.get("next_check_at") or 0),
            "error": _firmware_text(cloud_state.get("error"), 500),
        },
        "rollback": {**rollback, "available": bool(rollback.get("available") and not busy)},
        "operation": operation,
    }


def launch_firmware_operation(action: str) -> tuple[bool, str]:
    if action not in {"update", "rollback"}:
        return False, "Unsupported firmware operation."

    with _FIRMWARE_OPERATION_START_LOCK:
        state = firmware_control_public_state()
        operation = state["operation"]
        if operation.get("status") in {"starting", "running"}:
            return False, "Another firmware operation is already running."
        if action == "update" and not state["cloud"].get("available"):
            return False, "No newer firmware is available."
        if action == "rollback" and not state["rollback"].get("available"):
            return False, "No saved rollback version is available."
        if not FIRMWARE_OPERATION_SCRIPT.is_file():
            return False, "The firmware operation worker is unavailable."

        _write_firmware_operation_state(
            action,
            "starting",
            1,
            "Starting update…" if action == "update" else "Starting rollback…",
        )
        unit = f"bmi30-portal-firmware-{action}-{int(time.time())}-{os.getpid()}"
        command = [
            "/usr/bin/systemd-run",
            "--quiet",
            "--collect",
            f"--unit={unit}",
            "--property=Type=exec",
            "--property=Nice=10",
            f"--working-directory={FIRMWARE_WORKSPACE}",
            str(FIRMWARE_OPERATION_SCRIPT),
            action,
        ]
        try:
            proc = subprocess.run(
                command,
                check=False,
                capture_output=True,
                text=True,
                timeout=12.0,
            )
        except Exception as exc:
            message = _firmware_text(exc, 500)
            _write_firmware_operation_state(action, "failed", 1, "Unable to start.", message)
            return False, message
        if proc.returncode != 0:
            message = _firmware_text(
                proc.stderr or proc.stdout or "systemd-run returned an error",
                500,
            )
            _write_firmware_operation_state(action, "failed", 1, "Unable to start.", message)
            return False, message
        return True, "Firmware operation started."


def firmware_control_background() -> None:
    while True:
        if _firmware_operation_busy():
            _FIRMWARE_CONTROL_WAKE.wait(10.0)
            _FIRMWARE_CONTROL_WAKE.clear()
            continue
        check_firmware_update()
        _FIRMWARE_CONTROL_WAKE.wait(float(FIRMWARE_CHECK_INTERVAL_S))
        _FIRMWARE_CONTROL_WAKE.clear()


def _format_active_app_version(path: str) -> str:
    name = os.path.basename(str(path or "").strip())
    if not name:
        return ""
    match = re.match(r"^(BMI30\.\d+)\.py\.(\d{4}-\d{2}-\d{2})(?:-(.+))?$", name)
    if match:
        suffix = (match.group(3) or "").strip()
        return " ".join(part for part in (match.group(1), match.group(2), suffix) if part)
    if name.startswith("BMI30."):
        name = name[:-3] if name.endswith(".py") else name
        name = name.replace(".py.", " ")
        name = name.replace(".py", "")
    return " ".join(name.split())


def _natural_version_key(value: str) -> list[Any]:
    return [int(part) if part.isdigit() else part.lower() for part in re.split(r"(\d+)", value)]


def _unique_existing_text_paths(paths: tuple[str, ...]) -> list[str]:
    unique: list[str] = []
    seen: set[str] = set()
    for raw_path in paths:
        path = str(raw_path or "").strip()
        if not path or path in seen:
            continue
        seen.add(path)
        unique.append(path)
    return unique


def _bmi30_project_roots() -> tuple[str, ...]:
    script_dir = os.path.abspath(os.path.dirname(__file__))
    return (
        "/home/techaid/Documents",
        script_dir,
        os.path.dirname(script_dir),
    )


def _resolve_project_path(path: str) -> str:
    path = str(path or "").strip()
    if not path:
        return ""
    if os.path.isabs(path):
        return path
    for root in _bmi30_project_roots():
        candidate = os.path.join(root, path)
        if os.path.exists(candidate):
            return candidate
    return os.path.join(_bmi30_project_roots()[0], path)


def _split_active_env_candidates() -> list[str]:
    return _unique_existing_text_paths((
        os.getenv("BMI30_SPLIT_ACTIVE_ENV", ""),
        "/home/techaid/Documents/host/bmi30_split_active_version.env",
        os.path.join(os.path.dirname(__file__), "host", "bmi30_split_active_version.env"),
        "/usr/local/bin/host/bmi30_split_active_version.env",
    ))


def _find_latest_split_core_path() -> str:
    candidates: list[pathlib.Path] = []
    for root in _bmi30_project_roots():
        host_dir = pathlib.Path(root) / "host"
        if not host_dir.is_dir():
            continue
        candidates.extend(path for path in host_dir.glob("BMI30.001.py.*") if path.is_file())
    if not candidates:
        return ""
    latest = sorted(candidates, key=lambda path: _natural_version_key(path.name))[-1]
    try:
        return str(latest.relative_to(pathlib.Path("/home/techaid/Documents")))
    except ValueError:
        return str(latest)


def _split_version_from_core_path(path: str) -> str:
    name = os.path.basename(str(path or "").strip())
    resolved_path = _resolve_project_path(path)
    date_part = ""
    time_part = ""

    match = re.search(r"(\d{4}-\d{2}-\d{2})-([0-9]{2})([0-9]{2})", name)
    if match:
        date_part = match.group(1)
        time_part = f"{match.group(2)}{match.group(3)}"
    else:
        match = re.search(r"(\d{4}-\d{2}-\d{2})", name)
        if match:
            date_part = match.group(1)

    if not time_part and os.path.exists(resolved_path):
        try:
            mtime = dt.datetime.fromtimestamp(os.path.getmtime(resolved_path))
            if not date_part:
                date_part = mtime.strftime("%Y-%m-%d")
            time_part = mtime.strftime("%H%M")
        except Exception:
            pass

    if date_part and time_part:
        return f"{date_part}-{time_part}"
    if date_part:
        return date_part
    return name


def _format_split_system_label(version: str, core_path: str = "") -> str:
    version = str(version or "").strip()
    if not version:
        version = _split_version_from_core_path(core_path)
    if not version:
        return ""
    match = re.match(r"^(\d{4}-\d{2}-\d{2})-([0-9]{2})([0-9]{2})$", version)
    if match:
        return f"{match.group(1)} {match.group(2)}:{match.group(3)}"
    return version


def detect_bmi30_split_system_version() -> dict[str, str]:
    env_path = ""
    data: dict[str, str] = {}
    for candidate in _split_active_env_candidates():
        candidate_data = _read_key_value_file(candidate)
        if candidate_data:
            env_path = candidate
            data = candidate_data
            break

    version = os.getenv("BMI30_SPLIT_VERSION", "").strip() or data.get("BMI30_SPLIT_VERSION", "").strip()
    label = os.getenv("BMI30_SPLIT_LABEL", "").strip() or data.get("BMI30_SPLIT_LABEL", "").strip()
    selected_by = os.getenv("BMI30_SPLIT_SELECTED_BY", "").strip() or data.get("BMI30_SPLIT_SELECTED_BY", "").strip()
    selected_at = os.getenv("BMI30_SPLIT_SELECTED_AT", "").strip() or data.get("BMI30_SPLIT_SELECTED_AT", "").strip()
    core_path = os.getenv("BMI30_CORE_PATH", "").strip() or data.get("BMI30_CORE_PATH", "").strip()
    gui_path = os.getenv("BMI30_GUI_PATH", "").strip() or data.get("BMI30_GUI_PATH", "").strip()
    portal_path = os.getenv("BMI30_PORTAL_PATH", "").strip() or data.get("BMI30_PORTAL_PATH", "").strip()
    service_url = os.getenv("BMI30_SERVICE_URL", "").strip() or data.get("BMI30_SERVICE_URL", "").strip() or CORE_SERVICE_URL

    source = selected_by or ("env" if env_path else "")
    if core_path and not os.path.exists(_resolve_project_path(core_path)):
        source = "auto-latest-fallback"
        core_path = ""

    if not core_path:
        latest_core = _find_latest_split_core_path()
        if latest_core:
            core_path = latest_core
            source = source or "auto-latest-fallback"

    if not version:
        version = _split_version_from_core_path(core_path)
    if not label:
        label = _format_split_system_label(version, core_path)
    if not source:
        source = "unknown"

    return {
        "version": version or "",
        "label": label or "",
        "selected_by": selected_by or source,
        "selected_at": selected_at or "",
        "source": source,
        "core_path": core_path or "",
        "gui_path": gui_path or "",
        "portal_path": portal_path or "",
        "service_url": service_url,
        "active_env": env_path,
    }


def detect_rpi_software_version() -> str:
    for env_name in ("BMI30_RPI_FW_VERSION", "BMI30_RPI_SOFTWARE_VERSION", "BMI30_HOST_FW_VERSION"):
        value = os.getenv(env_name, "").strip()
        if value:
            return value

    firmware_release = detect_bmi30_firmware_release()
    release_version = format_firmware_version_with_date(firmware_release)
    if release_version:
        return release_version

    value = _read_first_text((
        "/etc/bmi30/rpi_fw_version",
        "/etc/bmi30/rpi_software_version",
        "/etc/bmi30/version",
        "/usr/local/share/bmi30/version",
        "/home/techaid/Documents/host/VERSION",
        "/home/techaid/Documents/VERSION",
    ))
    if value:
        return value.splitlines()[0].strip()

    split_version = detect_bmi30_split_system_version().get("label", "").strip()
    if split_version:
        return split_version

    app_path = os.getenv("BMI30_APP_PATH", "").strip()
    if not app_path:
        for env_path in (
            "/home/techaid/Documents/host/bmi30_active_version.env",
            "/usr/local/bin/host/bmi30_active_version.env",
            os.path.join(os.path.dirname(__file__), "host", "bmi30_active_version.env"),
        ):
            data = _read_key_value_file(env_path)
            app_path = data.get("BMI30_APP_PATH", "").strip()
            if app_path:
                break
    version = _format_active_app_version(app_path)
    if version:
        return version

    os_release = _read_key_value_file("/etc/os-release")
    return os_release.get("PRETTY_NAME", "").strip()


def format_rpi_identity(info: dict[str, str]) -> str:
    serial = str(info.get("serial") or "").strip() or "---"
    version = str(info.get("software_version") or "").strip() or "---"
    return f"{serial} / FW {version}"



def _now_monotonic() -> float:
    return time.monotonic()


def remember_portal_client(address: str) -> None:
    address = (address or "").strip()
    if not address:
        return
    now = _now_monotonic()
    _PORTAL_CLIENTS[address] = now
    for key, seen_at in list(_PORTAL_CLIENTS.items()):
        if now - seen_at > PORTAL_CLIENT_TTL_S:
            _PORTAL_CLIENTS.pop(key, None)


def count_portal_clients() -> int:
    now = _now_monotonic()
    for key, seen_at in list(_PORTAL_CLIENTS.items()):
        if now - seen_at > PORTAL_CLIENT_TTL_S:
            _PORTAL_CLIENTS.pop(key, None)
    return len(_PORTAL_CLIENTS)


def _load_config_json() -> dict[str, Any]:
    try:
        with open(CONFIG_JSON, "r", encoding="utf-8") as f:
            payload = json.load(f) or {}
        return payload if isinstance(payload, dict) else {}
    except Exception:
        return {}


def _save_config_json(payload: dict[str, Any]) -> None:
    directory = os.path.dirname(CONFIG_JSON) or "."
    os.makedirs(directory, exist_ok=True)
    tmp_path = f"{CONFIG_JSON}.tmp"
    try:
        previous_stat = os.stat(CONFIG_JSON)
    except Exception:
        previous_stat = None
    with open(tmp_path, "w", encoding="utf-8") as f:
        json.dump(payload, f, ensure_ascii=False, indent=2, sort_keys=True)
        f.write("\n")
    if previous_stat is not None:
        try:
            runtime_gid = os.stat("/home/techaid/Documents").st_gid
            os.chown(tmp_path, previous_stat.st_uid, runtime_gid)
        except Exception:
            pass
    try:
        os.chmod(tmp_path, 0o640)
    except Exception:
        pass
    os.replace(tmp_path, CONFIG_JSON)


def _float_form_value(form: dict[str, str], key: str, default: float, minimum: float, maximum: float) -> float:
    try:
        value = float(str(form.get(key, default)).strip())
    except Exception:
        value = float(default)
    return max(float(minimum), min(float(maximum), value))


def _normalize_avg_n(value: Any, default: int = DEFAULT_AVG_N) -> int:
    try:
        avg_n = int(value)
    except Exception:
        avg_n = int(default)
    if avg_n in AVG_N_VALUES:
        return avg_n
    return int(default) if int(default) in AVG_N_VALUES else DEFAULT_AVG_N


def load_default_avg_n() -> int:
    payload = _load_config_json()
    operation = payload.get("operation")
    operation_avg = operation.get("avg_n") if isinstance(operation, dict) else None
    return _normalize_avg_n(payload.get("avg_n", operation_avg), DEFAULT_AVG_N)


def save_default_avg_n(avg_n: int, rpi_avg_n: int = 1) -> None:
    avg_n = _normalize_avg_n(avg_n, DEFAULT_AVG_N)
    payload = _load_config_json()
    rpi_avg_n = _normalize_rpi_avg_n(rpi_avg_n)
    payload["avg_n"] = avg_n
    payload["rpi_avg_n"] = rpi_avg_n
    operation = payload.get("operation")
    if not isinstance(operation, dict):
        operation = {}
    operation["avg_n"] = avg_n
    operation["rpi_avg_n"] = rpi_avg_n
    operation["updated_at"] = int(time.time())
    payload["operation"] = operation
    _save_config_json(payload)


def _normalize_rpi_avg_n(value) -> int:
    depth = int(value)
    if isinstance(value, bool) or str(value).strip() != str(depth) or not 1 <= depth <= 12:
        raise ValueError("Raspberry averaging must be an integer from 1 to 12")
    return depth


def load_default_rpi_avg_n() -> int:
    payload = _load_config_json()
    operation = payload.get("operation", {})
    fallback = operation.get("rpi_avg_n", 1) if isinstance(operation, dict) else 1
    try:
        return _normalize_rpi_avg_n(payload.get("rpi_avg_n", fallback))
    except (ValueError, TypeError):
        return 1


def avg_n_from_form(form: dict[str, str]) -> int:
    return _normalize_avg_n(form.get("avg_n"), load_default_avg_n())


def _int_form_value(form: dict[str, str], key: str, default: int, minimum: int, maximum: int) -> int:
    try:
        value = int(str(form.get(key, default)).strip())
    except Exception:
        value = int(default)
    return max(int(minimum), min(int(maximum), value))


def _bool_form_value(form: dict[str, str], key: str, default: bool = False) -> bool:
    raw = form.get(key, "1" if default else "0")
    return str(raw).strip().lower() in {"1", "true", "yes", "on", "y", "t"}


def _normalize_sound_config(raw: Any = None) -> dict[str, Any]:
    source = raw if isinstance(raw, dict) else {}
    cfg = dict(DEFAULT_SOUND_CONFIG)
    cfg.update({k: source.get(k, v) for k, v in DEFAULT_SOUND_CONFIG.items()})
    cfg["enabled"] = bool(cfg.get("enabled", False))
    cfg["volume_percent"] = round(_float_form_value(cfg, "volume_percent", 100.0, 0.0, 100.0), 1)
    cfg["upper_frequency_hz"] = round(_float_form_value(cfg, "upper_frequency_hz", 4000.0, 1.0, 20000.0), 1)
    cfg["lower_frequency_hz"] = round(_float_form_value(cfg, "lower_frequency_hz", 1000.0, 1.0, 20000.0), 1)
    cfg["phase_upper_min_hz"] = round(_float_form_value(cfg, "phase_upper_min_hz", 1000.0, 1.0, 20000.0), 1)
    cfg["phase_upper_max_hz"] = round(_float_form_value(cfg, "phase_upper_max_hz", 3000.0, 1.0, 20000.0), 1)
    cfg["phase_lower_min_hz"] = round(_float_form_value(cfg, "phase_lower_min_hz", 2000.0, 1.0, 20000.0), 1)
    cfg["phase_lower_max_hz"] = round(_float_form_value(cfg, "phase_lower_max_hz", 4000.0, 1.0, 20000.0), 1)
    cfg["minimum_duration_ms"] = _int_form_value(cfg, "minimum_duration_ms", 150, 0, 60000)
    cfg["minimum_tone_cycles"] = _int_form_value(cfg, "minimum_tone_cycles", 1, 1, 1000)
    if cfg["phase_upper_max_hz"] < cfg["phase_upper_min_hz"]:
        cfg["phase_upper_min_hz"], cfg["phase_upper_max_hz"] = cfg["phase_upper_max_hz"], cfg["phase_upper_min_hz"]
    if cfg["phase_lower_max_hz"] < cfg["phase_lower_min_hz"]:
        cfg["phase_lower_min_hz"], cfg["phase_lower_max_hz"] = cfg["phase_lower_max_hz"], cfg["phase_lower_min_hz"]
    legacy_test = bool(source.get("test_enabled", cfg.get("test_enabled", False)))
    cfg["test_upper_enabled"] = bool(source.get("test_upper_enabled", legacy_test))
    cfg["test_lower_enabled"] = bool(source.get("test_lower_enabled", legacy_test))
    if cfg["test_upper_enabled"] and cfg["test_lower_enabled"]:
        cfg["test_lower_enabled"] = False
    cfg["test_enabled"] = bool(cfg["test_upper_enabled"] or cfg["test_lower_enabled"])
    cfg["volume_scale"] = "ui_0_100_pwm_0_50"
    return cfg


def _normalize_lcd_role_overlay(raw: Any = None) -> dict[str, Any]:
    source = raw if isinstance(raw, dict) else {}
    def seconds(key: str) -> int:
        try:
            value = int(source.get(key, 4))
        except Exception:
            value = 4
        return max(1, min(5, value))
    return {
        "enabled": _bool_form_value({"enabled": str(source.get("enabled", "0"))}, "enabled", False),
        "period_s": seconds("period_s"),
        "duration_s": seconds("duration_s"),
    }


def load_lcd_role_overlay() -> dict[str, Any]:
    payload = _load_config_json()
    return _normalize_lcd_role_overlay(payload.get("lcd_role_overlay"))


def save_lcd_role_overlay(cfg: dict[str, Any]) -> None:
    payload = _load_config_json()
    payload["lcd_role_overlay"] = _normalize_lcd_role_overlay(cfg)
    payload["lcd_role_overlay_updated_at"] = int(time.time())
    _save_config_json(payload)


def lcd_role_overlay_from_form(form: dict[str, str]) -> dict[str, Any]:
    return _normalize_lcd_role_overlay({
        "enabled": _bool_form_value(form, "lcd_role_overlay_enabled", False),
        "period_s": form.get("lcd_role_overlay_period_s", 4),
        "duration_s": form.get("lcd_role_overlay_duration_s", 4),
    })


def apply_lcd_role_overlay_to_core(cfg: dict[str, Any], persist: bool = True) -> tuple[bool, str, dict[str, Any]]:
    cfg = _normalize_lcd_role_overlay(cfg)
    payload = {"action": "lcd_role_overlay", "params": dict(cfg, persist=bool(persist))}
    try:
        req = Request(
            f"{CORE_SERVICE_URL}/api/command",
            data=json.dumps(payload).encode("utf-8"),
            headers={"Content-Type": "application/json", "X-BMI30-Source": "portal_lcd_role_overlay"},
            method="POST",
        )
        with urlopen(req, timeout=3.0) as response:
            result = json.loads(response.read().decode("utf-8") or "{}")
    except Exception as exc:
        return False, f"Unable to contact BMI30 core service: {exc}", dict(cfg, applied=False, pending=True)
    actual = result.get("lcd_role_overlay") if isinstance(result, dict) else None
    if not isinstance(actual, dict):
        actual = dict(cfg, applied=False, pending=True)
    if not isinstance(result, dict) or not bool(result.get("ok", False)):
        return False, str(result.get("error") or "BMI30 core rejected LCD role overlay"), actual
    return True, "LCD role overlay sent to BMI30 core service", actual


def load_sound_config_from_core() -> dict[str, Any] | None:
    try:
        with urlopen(f"{CORE_SERVICE_URL}/api/status", timeout=0.5) as response:
            status = json.loads(response.read().decode("utf-8") or "{}")
        sound = (status or {}).get("sound")
        if not isinstance(sound, dict):
            return None
        return _normalize_sound_config(sound)
    except Exception:
        return None


def load_sound_config() -> dict[str, Any]:
    payload = _load_config_json()
    raw = payload.get("sound_settings")
    if not isinstance(raw, dict):
        raw = payload.get("sound")
    source = raw if isinstance(raw, dict) else {}
    if "sound_enabled" in payload and "enabled" not in source:
        source = dict(source)
        source["enabled"] = payload.get("sound_enabled")
    if source and source.get("volume_scale") != "ui_0_100_pwm_0_50" and "volume_percent" in source:
        try:
            source = dict(source)
            source["volume_percent"] = min(100.0, max(0.0, float(source.get("volume_percent", 50.0)) * 2.0))
        except Exception:
            pass
    cfg = _normalize_sound_config(source)
    core_cfg = load_sound_config_from_core()
    if core_cfg is not None:
        if not source:
            cfg = core_cfg
        else:
            cfg["test_enabled"] = bool(core_cfg.get("test_enabled", False))
            cfg["test_upper_enabled"] = bool(core_cfg.get("test_upper_enabled", False))
            cfg["test_lower_enabled"] = bool(core_cfg.get("test_lower_enabled", False))
    return _normalize_sound_config(cfg)


def save_sound_config(cfg: dict[str, Any]) -> None:
    payload = _load_config_json()
    saved = _normalize_sound_config(cfg)
    saved["test_enabled"] = False
    saved["test_upper_enabled"] = False
    saved["test_lower_enabled"] = False
    payload["sound_enabled"] = bool(saved["enabled"])
    payload["sound_settings"] = saved
    payload["sound_settings_updated_at"] = int(time.time())
    _save_config_json(payload)


def sound_config_from_form(form: dict[str, str]) -> dict[str, Any]:
    return _normalize_sound_config({
        "enabled": _bool_form_value(form, "sound_enabled", False),
        "volume_percent": _float_form_value(form, "sound_volume_percent", 100.0, 0.0, 100.0),
        "upper_frequency_hz": _float_form_value(form, "sound_upper_frequency_hz", 4000.0, 1.0, 20000.0),
        "lower_frequency_hz": _float_form_value(form, "sound_lower_frequency_hz", 1000.0, 1.0, 20000.0),
        "phase_upper_min_hz": _float_form_value(form, "sound_phase_upper_min_hz", 1000.0, 1.0, 20000.0),
        "phase_upper_max_hz": _float_form_value(form, "sound_phase_upper_max_hz", 3000.0, 1.0, 20000.0),
        "phase_lower_min_hz": _float_form_value(form, "sound_phase_lower_min_hz", 2000.0, 1.0, 20000.0),
        "phase_lower_max_hz": _float_form_value(form, "sound_phase_lower_max_hz", 4000.0, 1.0, 20000.0),
        "minimum_duration_ms": _int_form_value(form, "sound_minimum_duration_ms", 150, 0, 60000),
        "minimum_tone_cycles": _int_form_value(form, "sound_minimum_tone_cycles", 1, 1, 1000),
        "test_upper_enabled": _bool_form_value(form, "sound_test_upper_enabled", False),
        "test_lower_enabled": _bool_form_value(form, "sound_test_lower_enabled", False),
    })


def apply_sound_config_to_core(cfg: dict[str, Any], persist: bool = True) -> tuple[bool, str]:
    cfg = _normalize_sound_config(cfg)
    payload = {
        "action": "sound_settings",
        "params": {
            "enabled": bool(cfg["enabled"]),
            "volume_percent": float(cfg["volume_percent"]),
            "upper_frequency_hz": float(cfg["upper_frequency_hz"]),
            "lower_frequency_hz": float(cfg["lower_frequency_hz"]),
            "phase_upper_min_hz": float(cfg["phase_upper_min_hz"]),
            "phase_upper_max_hz": float(cfg["phase_upper_max_hz"]),
            "phase_lower_min_hz": float(cfg["phase_lower_min_hz"]),
            "phase_lower_max_hz": float(cfg["phase_lower_max_hz"]),
            "minimum_duration_ms": int(cfg["minimum_duration_ms"]),
            "minimum_tone_cycles": int(cfg["minimum_tone_cycles"]),
            "test_enabled": bool(cfg["test_enabled"]),
            "test_upper_enabled": bool(cfg["test_upper_enabled"]),
            "test_lower_enabled": bool(cfg["test_lower_enabled"]),
            "volume_scale": "ui_0_100_pwm_0_50",
            "persist": bool(persist),
        },
    }
    try:
        req = Request(
            f"{CORE_SERVICE_URL}/api/command",
            data=json.dumps(payload).encode("utf-8"),
            headers={"Content-Type": "application/json", "X-BMI30-Source": "portal_sound_settings"},
            method="POST",
        )
        with urlopen(req, timeout=3.0) as response:
            result = json.loads(response.read().decode("utf-8") or "{}")
    except Exception as exc:
        return False, f"Unable to contact BMI30 core service: {exc}"
    if not isinstance(result, dict) or not bool(result.get("ok", False)):
        return False, str(result.get("error") or "BMI30 core service rejected sound settings")
    return True, "Sound settings sent to BMI30 core service"


def _noise_unit_value(value: Any, default: str = "adc") -> str:
    try:
        unit = str(value or default).strip().lower()
    except Exception:
        unit = str(default or "adc")
    if unit in {"percent", "pct", "%"}:
        return "percent"
    return "adc"


def _det_confirmation_change_mode(value=None, legacy_enabled=False):
    """An explicit mode wins over the legacy enabled flag, including explicit off."""
    if value is None:
        return "up" if str(legacy_enabled).strip().lower() in ("true", "1", "yes", "on") else "off"
    mode = str(value).strip().lower()
    if mode not in ("up", "down", "either", "off"):
        raise ValueError("Invalid confirmation amplitude change mode")
    return mode


def _normalize_tag_detection_config(raw: Any = None) -> dict[str, Any]:
    source = raw if isinstance(raw, dict) else {}
    cfg = dict(DEFAULT_TAG_DETECTION_CONFIG)
    cfg.update({k: source.get(k, v) for k, v in DEFAULT_TAG_DETECTION_CONFIG.items()})
    cfg["enabled0"] = bool(cfg.get("enabled0", True))
    cfg["enabled1"] = bool(cfg.get("enabled1", True))
    cfg["confirm0"] = _int_form_value(cfg, "confirm0", 2, 1, 6)
    cfg["confirm1"] = _int_form_value(cfg, "confirm1", 2, 1, 6)
    cfg["common_mode_enabled"] = _bool_form_value(cfg, "common_mode_enabled", False)
    cfg["common_mode_require_pair"] = _bool_form_value(cfg, "common_mode_require_pair", True)
    cfg["common_mode_same_lag"] = _bool_form_value(cfg, "common_mode_same_lag", True)
    cfg["common_mode_strength"] = round(_float_form_value(cfg, "common_mode_strength", 100.0, 0.0, 100.0), 3)
    cfg["common_mode_balance"] = round(_float_form_value(cfg, "common_mode_balance", 1.0, 0.1, 10.0), 3)
    cfg["common_mode_radius"] = _int_form_value(cfg, "common_mode_radius", 0, 0, 6)
    cfg["common_mode_min_snr"] = round(_float_form_value(cfg, "common_mode_min_snr", 1.5, 0.0, 10.0), 3)
    cfg["common_mode_residual_threshold"] = round(_float_form_value(cfg, "common_mode_residual_threshold", 100.0, 5.0, 100.0), 3)
    cfg["confirm_phase_gate"] = _int_form_value(cfg, "confirm_phase_gate", 3, 0, 199)
    cfg["confirm_sample_diversity"] = _int_form_value(cfg, "confirm_sample_diversity", 0, 0, 5)
    cfg["confirm_change_mode"] = _det_confirmation_change_mode(cfg.get("confirm_change_mode"), cfg.get("confirm_growth_enabled", False))
    cfg["confirm_growth_enabled"] = cfg["confirm_change_mode"] != "off"
    try:
        growth_ratio = float(cfg.get("confirm_growth_ratio", 2.0))
    except (TypeError, ValueError, OverflowError):
        growth_ratio = 2.0
    if not -float("inf") < growth_ratio < float("inf"):
        growth_ratio = 2.0
    cfg["confirm_growth_ratio"] = round(max(1.0, min(100.0, growth_ratio)), 4)
    cfg["impulse_guard_enabled"] = _bool_form_value(cfg, "impulse_guard_enabled", False)
    cfg["threshold0"] = round(_float_form_value(cfg, "threshold0", 2.0, 1.0, 100.0), 1)
    cfg["threshold1"] = round(_float_form_value(cfg, "threshold1", 2.0, 1.0, 100.0), 1)
    cfg["threshold_high0"] = round(_float_form_value(cfg, "threshold_high0", 5.0, 1.0, 100.0), 1)
    cfg["threshold_high1"] = round(_float_form_value(cfg, "threshold_high1", 5.0, 1.0, 100.0), 1)
    cfg["ratio_noise_max_u16"] = round(_float_form_value(cfg, "ratio_noise_max_u16", 10.0, 0.1, 65535.0), 3)
    cfg["auto_floor_u16"] = round(_float_form_value(cfg, "auto_floor_u16", 10.0, 0.0, 65535.0), 3)
    cfg["auto_slope"] = round(_float_form_value(cfg, "auto_slope", 5.0, 0.1, 100.0), 3)
    cfg["auto0"] = bool(cfg.get("auto0", False))
    cfg["auto1"] = bool(cfg.get("auto1", False))
    cfg["filter_amplitude0"] = bool(cfg.get("filter_amplitude0", True))
    cfg["filter_amplitude1"] = bool(cfg.get("filter_amplitude1", True))
    cfg["filter_shape0"] = bool(cfg.get("filter_shape0", True))
    cfg["filter_shape1"] = bool(cfg.get("filter_shape1", True))
    cfg["filter_phase0"] = bool(cfg.get("filter_phase0", True))
    cfg["filter_phase1"] = bool(cfg.get("filter_phase1", True))
    cfg["filter_noise_adapt0"] = bool(cfg.get("filter_noise_adapt0", True))
    cfg["filter_noise_adapt1"] = bool(cfg.get("filter_noise_adapt1", True))
    cfg["noise_window_s"] = round(_float_form_value(cfg, "noise_window_s", 1.0, 0.05, 10.0), 3)
    cfg["noise_area_percent"] = _int_form_value(cfg, "noise_area_percent", 50, 5, 95)
    cfg["noise_up0"] = _int_form_value(cfg, "noise_up0", 24, 1, 65535)
    cfg["noise_up1"] = _int_form_value(cfg, "noise_up1", 24, 1, 65535)
    cfg["noise_down0"] = _int_form_value(cfg, "noise_down0", 3, 1, 65535)
    cfg["noise_down1"] = _int_form_value(cfg, "noise_down1", 3, 1, 65535)
    cfg["noise_unit0"] = _noise_unit_value(cfg.get("noise_unit0", "adc"), "adc")
    cfg["noise_unit1"] = _noise_unit_value(cfg.get("noise_unit1", "adc"), "adc")
    cfg["burst_gate0"] = _bool_form_value(cfg, "burst_gate0", True)
    cfg["burst_gate1"] = _bool_form_value(cfg, "burst_gate1", True)
    cfg["burst_blank_s0"] = round(_float_form_value(cfg, "burst_blank_s0", 0.08, 0.0, 1.0), 3)
    cfg["burst_blank_s1"] = round(_float_form_value(cfg, "burst_blank_s1", 0.08, 0.0, 1.0), 3)
    cfg["burst_max_ratio0"] = round(_float_form_value(cfg, "burst_max_ratio0", 8.0, 0.0, 100.0), 1)
    cfg["burst_max_ratio1"] = round(_float_form_value(cfg, "burst_max_ratio1", 8.0, 0.0, 100.0), 1)
    cfg["smooth_mode"] = _int_form_value(cfg, "smooth_mode", 0, 0, 5)
    filter_slots = _normalize_tag_response_filter_slots(cfg)
    cfg["tag_filter_slot1"] = filter_slots[0]
    cfg["tag_filter_slot2"] = filter_slots[1]
    cfg["tag_filter_slot3"] = filter_slots[2]
    cfg["filter_casino"] = bool(cfg.get("filter_casino", False))
    cfg["filter_barkhausen"] = bool(cfg.get("filter_barkhausen", False))
    cfg["filter_microwire"] = bool(cfg.get("filter_microwire", False))
    cfg["filter_paper"] = bool(cfg.get("filter_paper", False))
    if "peak_index_min" not in source and "peak_index_max" not in source:
        legacy_enabled = _bool_form_value(source, "peak_thirds_limit_enabled", False)
        legacy_type = str(source.get("peak_thirds_limit_type", "microwire") or "microwire").strip().lower()
        legacy_barkhausen = legacy_type in {"barkhausen", "bark", "b"}
        cfg["peak_index_min"] = 67 if legacy_enabled and legacy_barkhausen else 0
        cfg["peak_index_max"] = 66 if legacy_enabled and not legacy_barkhausen else 199
    cfg["peak_index_min"] = _int_form_value(cfg, "peak_index_min", 0, 0, 199)
    cfg["base_width_enabled"] = _bool_form_value(cfg, "base_width_enabled", False)
    cfg["base_width_max"] = _int_form_value(cfg, "base_width_max", 24, 10, 100)
    cfg["peak_index_max"] = _int_form_value(cfg, "peak_index_max", 199, 0, 199)
    if cfg["peak_index_max"] < cfg["peak_index_min"]:
        cfg["peak_index_max"] = cfg["peak_index_min"]
    cfg["barkhausen_radius"] = _int_form_value(cfg, "barkhausen_radius", 24, 1, 120)
    cfg["barkhausen_frac"] = round(_float_form_value(cfg, "barkhausen_frac", 0.22, 0.01, 1.0), 3)
    cfg["barkhausen_min_width"] = _int_form_value(cfg, "barkhausen_min_width", 4, 1, 120)
    cfg["barkhausen_max_span"] = _int_form_value(cfg, "barkhausen_max_span", 140, 1, 200)
    cfg["barkhausen_min_product_level"] = _int_form_value(cfg, "barkhausen_min_product_level", 800000, 0, 2147483647)
    cfg["barkhausen_max_product_level"] = _int_form_value(cfg, "barkhausen_max_product_level", 20000000, 0, 2147483647)
    if cfg["barkhausen_max_product_level"] and cfg["barkhausen_max_product_level"] < cfg["barkhausen_min_product_level"]:
        cfg["barkhausen_max_product_level"] = cfg["barkhausen_min_product_level"]
    cfg["barkhausen_max_total_fraction"] = round(_float_form_value(cfg, "barkhausen_max_total_fraction", 0.82, 0.01, 1.0), 3)
    cfg["barkhausen_all_quarter_frac"] = round(_float_form_value(cfg, "barkhausen_all_quarter_frac", 0.45, 0.01, 1.0), 3)
    cfg["phase_max_shift"] = _int_form_value(cfg, "phase_max_shift", 12, 0, 80)
    cfg["phase_shift_penalty"] = round(_float_form_value(cfg, "phase_shift_penalty", 0.02, 0.0, 1.0), 4)
    cfg["mark_window_start_frac"] = round(_float_form_value(cfg, "mark_window_start_frac", 0.05, 0.0, 0.95), 4)
    mark_window_end_default = 0.95 if cfg["filter_barkhausen"] else 0.45
    cfg["mark_window_end_frac"] = round(_float_form_value(cfg, "mark_window_end_frac", mark_window_end_default, 0.01, 1.0), 4)
    if cfg["filter_barkhausen"] and cfg["mark_window_end_frac"] < 0.90:
        cfg["mark_window_end_frac"] = 0.95
    if cfg["mark_window_end_frac"] <= cfg["mark_window_start_frac"]:
        cfg["mark_window_end_frac"] = min(1.0, round(float(cfg["mark_window_start_frac"]) + 0.01, 4))
    cfg["mark_gap"] = _int_form_value(cfg, "mark_gap", 21, 1, 160)
    cfg["mark_gap_tol"] = _int_form_value(cfg, "mark_gap_tol", 7, 0, 80)
    cfg["mark_second_frac"] = round(_float_form_value(cfg, "mark_second_frac", 0.18, 0.01, 1.0), 3)
    cfg["mark_valley_frac"] = round(_float_form_value(cfg, "mark_valley_frac", 0.70, 0.01, 0.99), 3)
    cfg["mark_multi_max_humps"] = _int_form_value(cfg, "mark_multi_max_humps", 3, 1, 12)
    cfg["locality_max_outside_peaks"] = _int_form_value(cfg, "locality_max_outside_peaks", 1, 0, 20)
    cfg["locality_outside_peak_frac"] = round(_float_form_value(cfg, "locality_outside_peak_frac", 0.35, 0.01, 1.0), 3)
    return cfg


def render_common_mode_controls(raw: Any = None) -> str:
    cfg = _normalize_tag_detection_config(raw)
    checked = " checked" if cfg["common_mode_enabled"] else ""
    fields = (
        ("common_mode_strength", "Subtraction strength, %", 0, 100, 5, "100% subtracts the full reference level; 0% disables subtraction."),
        ("common_mode_balance", "Upper / lower channel balance", 0.1, 10, 0.05, "Ratio of the common-noise product levels: upper / lower. Use 1 for equal levels."),
        ("common_mode_radius", "Phase tolerance, ± samples", 0, 6, 1, "0 uses the same sample. A larger tolerance uses the strongest response from the other channel within this range, including secondary peaks."),
        ("common_mode_min_snr", "Minimum reference peak / noise", 0, 10, 0.1, "A reference peak below this noise ratio is not subtracted. Set to 0 to skip this check."),
        ("common_mode_residual_threshold", "Residual threshold, % of original", 5, 100, 5, "After subtraction, the peak must remain at or above this percentage of the original threshold. Lower values increase sensitivity but may admit more noise."),
    )
    rows = []
    for key, label, lo, hi, step, help_text in fields:
        value = f"{float(cfg[key]):g}"
        rows.append(f'<tr><td class="tag-desc"><span class="tag-param">{html.escape(label)} '
                    f'<b class="help tag-help" tabindex="0" aria-label="{html.escape(help_text, quote=True)}" data-tip="{html.escape(help_text, quote=True)}">?</b></span></td>'
                    f'<td class="tag-channel"><label class="tag-control"><input type="number" name="{key}" min="{lo}" max="{hi}" step="{step}" value="{value}" aria-label="{html.escape(label, quote=True)}"></label></td></tr>')
    switches = ''
    for key, label, tip in (
        ('common_mode_require_pair', 'Require a synchronized reference', 'After the pairing wait expires, a missing or invalid reference resets detection confirmations.'),
        ('common_mode_same_lag', 'Also check the reference with the same phase shift', 'Use the candidate phase shift for the other channel as an additional check. Both checks must pass; existing rejections are preserved.'),
    ):
        flag = ' checked' if cfg[key] else ''
        switches += (f'<label class="tag-control"><input type="hidden" name="{key}" value="0">'
                     f'<input type="checkbox" name="{key}" value="1"{flag}>{label} '
                     f'<b class="help tag-help" tabindex="0" aria-label="{tip}" data-tip="{tip}">?</b></label>')
    return ('<div class="section" data-common-mode-controls><h2>Common-Mode Noise Suppression</h2>'
            '<p>An additional peak check after multiplication. Includes secondary peaks at matching phase positions in the other channel.</p>'
            '<label class="tag-control"><input type="hidden" name="common_mode_enabled" value="0">'
            f'<input type="checkbox" name="common_mode_enabled" value="1"{checked}>Enable subtraction of the other channel</label>'
            + switches + '<table class="tag-settings"><tbody>' + ''.join(rows) + '</tbody></table>'
            '<p class="muted">Stronger subtraction may weaken a tag detected by both antennas. '
            'These settings apply to real-time detection. The original waveforms are preserved.</p>'
            '<button type="submit" name="apply" value="1">Save and Apply</button></div>')


def load_tag_detection_config() -> dict[str, Any]:
    payload = _load_config_json()
    raw = payload.get("tag_detection")
    source = raw if isinstance(raw, dict) else payload
    cfg = _normalize_tag_detection_config(source)
    if "smooth_mode" not in source and "smooth_mode" in payload:
        cfg["smooth_mode"] = _int_form_value(payload, "smooth_mode", 0, 0, 5)
    core_backfill_keys = CORE_TAG_DETECTION_KEYS
    missing_core = any(key not in source for key in core_backfill_keys)
    if missing_core:
        core_cfg = load_tag_detection_config_from_core()
        if core_cfg is not None:
            for key in core_backfill_keys:
                if key not in source and key in core_cfg:
                    cfg[key] = core_cfg[key]
    return _normalize_tag_detection_config(cfg)


def _validate_sample_diversity(cfg):
    if cfg.get("confirm_growth_enabled", False) and any(cfg[f"enabled{ch}"] and int(cfg[f"confirm{ch}"]) < 2 for ch in (0, 1)):
        raise ValueError("Amplitude change requires at least two confirmations for each enabled channel.")
    minimum = int(cfg.get("confirm_sample_diversity", 0))
    if minimum > int(cfg["confirm_phase_gate"]) or any(
        cfg[f"enabled{ch}"] and minimum >= int(cfg[f"confirm{ch}"]) for ch in (0, 1)
    ):
        raise ValueError("Sample diversity must be lower than confirmations and no greater than the phase gate.")


def save_tag_detection_config(cfg: dict[str, Any]) -> None:
    _validate_sample_diversity(_normalize_tag_detection_config(cfg))
    payload = _load_config_json()
    payload["tag_detection"] = _normalize_tag_detection_config(cfg)
    for key in ("confirm_change_mode", "confirm_growth_enabled", "confirm_growth_ratio"):
        payload[key] = payload["tag_detection"][key]
    payload["impulse_guard_enabled"] = bool(payload["tag_detection"]["impulse_guard_enabled"])
    payload["confirm_sample_diversity"] = int(payload["tag_detection"]["confirm_sample_diversity"])
    payload["noise_area_percent"] = int(payload["tag_detection"]["noise_area_percent"])
    payload["smooth_mode"] = int(payload["tag_detection"]["smooth_mode"])
    for key in ('common_mode_enabled', 'common_mode_require_pair', 'common_mode_same_lag', 'common_mode_strength', 'common_mode_balance', 'common_mode_radius', 'common_mode_min_snr', 'common_mode_residual_threshold'):
        payload[key] = payload["tag_detection"][key]
    payload["tag_detection_updated_at"] = int(time.time())
    _save_config_json(payload)


