_BMI30_BLUETOOTH_REMOTE_TEST = None
_BMI30_BLUETOOTH_REMOTE_LOCK = threading.Lock()


def bmi30_bluetooth_remote_test():
    global _BMI30_BLUETOOTH_REMOTE_TEST
    with _BMI30_BLUETOOTH_REMOTE_LOCK:
        if _BMI30_BLUETOOTH_REMOTE_TEST is None:
            import sys
            core = pathlib.Path(_resolve_project_path(detect_bmi30_split_system_version()['core_path']))
            directory = core.parent
            module_path = directory / 'bmi30_bluetooth_remote_test.py'
            if str(directory) not in sys.path:
                sys.path.insert(0, str(directory))
            spec = importlib.util.spec_from_file_location('bmi30_bluetooth_remote_test', module_path)
            module = importlib.util.module_from_spec(spec)
            sys.modules[spec.name] = module
            spec.loader.exec_module(module)
            _BMI30_BLUETOOTH_REMOTE_TEST = module.BluetoothRemoteTest()
        return _BMI30_BLUETOOTH_REMOTE_TEST


def bmi30_bluetooth_remote_request(handler, action, *, send_body=True):
    if (handler._get_portal_session() is None or
            handler.headers.get('X-BMI30-Bluetooth-Test') != '1' or
            not bmi30_usb_origin_allowed(handler)):
        handler._send_json_response({'ok': False, 'error': 'Not authorized.'}, HTTPStatus.FORBIDDEN,
                                    send_body=send_body)
        return
    try:
        if action == 'events':
            query = parse_qs(urlsplit(handler.path).query)
            test_id = str(query.get('test_id', [''])[0])
            cursor = int(query.get('cursor', ['0'])[0])
            if not test_id or cursor < 0:
                raise ValueError('Select a running remote test and valid event cursor')
            state = bmi30_bluetooth_remote_test().snapshot(test_id, cursor, refresh=send_body)
        else:
            length = int(handler.headers.get('Content-Length', '0') or '0')
            if not 0 < length <= 4096:
                handler.close_connection = True
                raise ValueError('Invalid remote-test request size')
            raw = handler.rfile.read(length)
            if len(raw) != length:
                raise ValueError('Incomplete remote-test request')
            body = json.loads(raw.decode('utf-8'))
            if not isinstance(body, dict):
                raise ValueError('Expected a remote-test request object')
            if action == 'start':
                state = bmi30_bluetooth_remote_test().start(body.get('mac'))
            elif action == 'stop':
                test_id = body.get('test_id')
                if not isinstance(test_id, str) or not test_id:
                    raise ValueError('Select a running remote test')
                state = bmi30_bluetooth_remote_test().stop(test_id)
            else:
                raise ValueError('Unsupported remote-test action')
        code = HTTPStatus.OK if state.get('ok') else HTTPStatus.CONFLICT
        handler._send_json_response(state, code, send_body=send_body)
    except (ValueError, TypeError, UnicodeError) as exc:
        handler._send_json_response({'ok': False, 'error': str(exc)}, HTTPStatus.BAD_REQUEST,
                                    send_body=send_body)
    except Exception:
        handler._send_json_response({'ok': False, 'error': 'Bluetooth remote test is unavailable.'},
                                    HTTPStatus.SERVICE_UNAVAILABLE, send_body=send_body)


class HotspotInfoHandler(BaseHTTPRequestHandler):
    server_version = "BMI30HotspotInfo/1.0"

    def log_message(self, fmt: str, *args: Any) -> None:
        return

    def _is_tls(self) -> bool:
        return isinstance(self.request, ssl.SSLSocket)

    def _request_forwarded_host(self) -> str | None:
        forwarded = self.headers.get("X-Forwarded-Host") or self.headers.get("Forwarded")
        if not forwarded:
            return self.headers.get("Host") or None

        candidate = forwarded.strip()
        if not candidate:
            return self.headers.get("Host") or None

        if candidate.startswith("[") and "]" in candidate:
            candidate = candidate[1:candidate.index("]")]
        elif candidate.count(":") == 1 and "//" not in candidate and not candidate.startswith("http"):
            candidate = candidate.split(":", 1)[0]

        if candidate.startswith("http://") or candidate.startswith("https://"):
            try:
                parsed = urlsplit(candidate)
            except ValueError:
                parsed = None
            if parsed is not None and parsed.netloc:
                return parsed.netloc.split("@", 1)[-1]

        if "=" in candidate and ";" not in candidate and not candidate.startswith("http"):
            # X-Forwarded-Host sometimes carries a comma list; keep the first host.
            candidate = candidate.split(",", 1)[0].strip()

        if candidate.startswith("\"") and candidate.endswith("\""):
            candidate = candidate[1:-1]

        if "forwarded" in self.headers.get("Forwarded", "").lower() and candidate:
            # Forwarded header is handled through the parsed 'host=' parameter below.
            pass

        if self.headers.get("Forwarded"):
            for part in self.headers.get("Forwarded", "").split(","):
                item = part.strip()
                if not item:
                    continue
                for param in item.split(";"):
                    key, sep, value = param.strip().partition("=")
                    if key.lower() == "host" and sep:
                        val = value.strip().strip('"')
                        if val:
                            return val

        if "http" not in candidate and "," in candidate:
            candidate = candidate.split(",", 1)[0].strip()

        return candidate or self.headers.get("Host") or None

    def _request_forwarded_scheme(self) -> str | None:
        forwarded_proto = self.headers.get("X-Forwarded-Proto")
        if forwarded_proto:
            return forwarded_proto.split(",", 1)[0].strip().lower() or None

        forwarded = self.headers.get("Forwarded")
        if not forwarded:
            return None
        for part in forwarded.split(","):
            item = part.strip()
            if not item:
                continue
            for param in item.split(";"):
                key, sep, value = param.strip().partition("=")
                if key.lower() == "proto" and sep:
                    return value.strip().strip('"').lower() or None
        return None

    def _preferred_scheme(self) -> str:
        forwarded_scheme = self._request_forwarded_scheme()
        if forwarded_scheme:
            return forwarded_scheme
        if self._is_tls() or (is_https_enabled() and FORCE_HTTPS):
            return "https"
        return "http"

    def _relative_app_url(self, path: str) -> str:
        """Return a browser URL relative to the mounted portal application root."""
        parsed = urlsplit(path)
        if parsed.scheme or parsed.netloc:
            return path

        target_path = parsed.path or "/"
        if not target_path.startswith("/"):
            target_path = f"/{target_path}"

        request_path = urlsplit(self.path).path or "/"
        request_dir = posixpath.dirname(request_path) or "/"
        relative_path = posixpath.relpath(target_path, start=request_dir)
        if target_path.endswith("/") and not relative_path.endswith("/"):
            relative_path = f"{relative_path}/"
        return urlunsplit(("", "", relative_path, parsed.query, parsed.fragment))

    def _absolute_url(self, path: str, scheme: str = "http") -> str:
        # Same-origin redirects must stay relative.  The Hub mounts every
        # Raspberry below /bmi30/device/<DEVICE_ID>/ and may rewrite absolute
        # Location headers.  A relative Location keeps that mount prefix once
        # and also works when the portal is opened directly on the Raspberry.
        if not path.startswith("/"):
            path = f"/{path}"

        external_scheme = self._request_forwarded_scheme() or ("https" if self._is_tls() else "http")
        if scheme == external_scheme:
            return self._relative_app_url(path)

        # Keep an absolute URL only when the redirect intentionally changes the
        # scheme (for example FORCE_HTTPS on a directly connected device).
        local_ip = ""
        try:
            local_ip = self.connection.getsockname()[0]
        except Exception:
            local_ip = ""

        if not local_ip or local_ip == "0.0.0.0":
            local_ip = HOTSPOT_IP

        port = HTTPS_PORT if scheme == "https" else PORT
        needs_port = (scheme == "https" and port != 443) or (scheme == "http" and port != 80)
        suffix = f":{port}" if needs_port else ""
        return f"{scheme}://{local_ip}{suffix}{path}"

    def _read_post_form(self) -> dict[str, str]:
        try:
            content_length = int(self.headers.get("Content-Length", "0"))
        except ValueError:
            content_length = 0
        raw = self.rfile.read(max(content_length, 0))
        parsed = parse_qs(raw.decode("utf-8", errors="replace"), keep_blank_values=True)
        # Checkbox + hidden fallback fields submit duplicate keys; use the last value.
        return {key: values[-1] if values else "" for key, values in parsed.items()}

    def _read_raw_post_body(self) -> bytes:
        try:
            content_length = int(self.headers.get("Content-Length", "0"))
        except ValueError:
            content_length = 0
        return self.rfile.read(max(content_length, 0))

    def _send_json_response(
        self,
        data: dict[str, Any],
        status: HTTPStatus = HTTPStatus.OK,
        *,
        send_body: bool = True,
    ) -> None:
        payload = json.dumps(data, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Cache-Control", "no-store, no-cache, must-revalidate, max-age=0")
        self.send_header("Content-Length", str(len(payload)))
        self.end_headers()
        if send_body:
            self.wfile.write(payload)

    def _read_cookie(self, name: str) -> str:
        raw_cookie = self.headers.get("Cookie", "")
        if not raw_cookie:
            return ""

        jar = SimpleCookie()
        try:
            jar.load(raw_cookie)
        except Exception:
            return ""

        morsel = jar.get(name)
        return morsel.value if morsel is not None else ""

    def _get_portal_session(self) -> dict[str, Any] | None:
        session = parse_portal_session_token(self._read_cookie(PORTAL_SESSION_COOKIE))
        if session is None:
            return None
        if int(session["exp"]) <= int(time.time()):
            return None
        return session

    def _send_redirect(
        self,
        location: str,
        *,
        status: HTTPStatus = HTTPStatus.FOUND,
        set_cookie: str | None = None,
    ) -> None:
        self.send_response(status)
        self.send_header("Location", location)
        if set_cookie:
            self.send_header("Set-Cookie", set_cookie)
        self.send_header("Cache-Control", "no-store")
        self.end_headers()

    def _redirect_portal_privacy_error(self, message: str) -> None:
        self._send_redirect(
            self._absolute_url(
                f"/portal?privacy_error=1&message={quote(message[:240])}#privacy",
                scheme=self._preferred_scheme(),
            ),
            status=HTTPStatus.SEE_OTHER,
        )

    def _require_portal_session(self) -> dict[str, Any] | None:
        session = self._get_portal_session()
        if session is None:
            self._send_redirect(
                self._absolute_url(with_rev("/login"), scheme=self._preferred_scheme()),
                set_cookie=build_expired_portal_session_cookie(secure=self._is_tls()),
            )
            return None
        remember_portal_client(self.client_address[0] if self.client_address else "")
        return session

    def _rewrite_core_html_for_portal(self, payload: bytes) -> bytes:
        text = payload.decode("utf-8", errors="replace")
        replacements = {
            "'/api/status'": "'portal-core/api/status'",
            '"/api/status"': '"portal-core/api/status"',
            "'/api/command'": "'portal-core/api/command'",
            '"/api/command"': '"portal-core/api/command"',
            "'/api/frame.bin?": "'portal-core/api/frame.bin?",
            '"/api/frame.bin?': '"portal-core/api/frame.bin?',
            "'/api/frame?": "'portal-core/api/frame?",
            '"/api/frame?': '"portal-core/api/frame?',
            "'/api/detection-review?": "'portal-core/api/detection-review?",
            '"/api/detection-review?': '"portal-core/api/detection-review?',
            "'/api/player-recording-upload?": "'portal-core/api/player-recording-upload?",
            '"/api/player-recording-upload?': '"portal-core/api/player-recording-upload?',
            "'/api/player-recording-download?": "'portal-core/api/player-recording-download?",
            '"/api/player-recording-download?': '"portal-core/api/player-recording-download?',
            "'/api/player-recording-voice-upload?": "'portal-core/api/player-recording-voice-upload?",
            '"/api/player-recording-voice-upload?': '"portal-core/api/player-recording-voice-upload?',
            "'/api/player-recording-voice-status?": "'portal-core/api/player-recording-voice-status?",
            '"/api/player-recording-voice-status?': '"portal-core/api/player-recording-voice-status?',
            "'/api/player-recording-voice-download?": "'portal-core/api/player-recording-voice-download?",
            '"/api/player-recording-voice-download?': '"portal-core/api/player-recording-voice-download?',
            "'/api/time?": "'portal-core/api/time?",
            '"/api/time?': '"portal-core/api/time?',
        }
        for old, new in replacements.items():
            text = text.replace(old, new)
        bootstrap = render_style_bootstrap()
        if "</head>" in text:
            text = text.replace("</head>", f"{bootstrap}\n</head>", 1)
        return text.encode("utf-8")

    def _proxy_core_request(self, send_body: bool, method: str = "GET", body: bytes | None = None) -> None:
        path = self.path.split("?", 1)[0]
        query = self.path.split("?", 1)[1] if "?" in self.path else ""
        if path == "/portal-core":
            core_path = "/"
        elif path.startswith("/portal-core/"):
            core_path = "/" + path[len("/portal-core/"):]
        else:
            core_path = "/"
        url = f"{CORE_SERVICE_URL}{core_path}"
        if query:
            url = f"{url}?{query}"
        headers = {"Accept": self.headers.get("Accept", "*/*")}
        content_type = self.headers.get("Content-Type")
        if content_type:
            headers["Content-Type"] = content_type
        for header_name in ("X-BMI30-Filename", "X-Filename", "X-BMI30-Voice-Utterances"):
            header_value = self.headers.get(header_name)
            if header_value:
                headers[header_name] = header_value
        try:
            if core_path.startswith("/api/player-recording-"):
                try:
                    timeout_s = float(os.getenv("BMI30_PLAYER_PROXY_TIMEOUT_S", "210") or 210.0)
                except Exception:
                    timeout_s = 210.0
                timeout_s = max(90.0, min(960.0, timeout_s))
            elif core_path == "/api/command":
                try:
                    timeout_s = float(os.getenv("BMI30_COMMAND_PROXY_TIMEOUT_S", "210") or 210.0)
                except Exception:
                    timeout_s = 210.0
                timeout_s = max(60.0, min(960.0, timeout_s))
            else:
                timeout_s = 4.0
            request = Request(url, data=body if method.upper() != "GET" else None, headers=headers, method=method.upper())
            with urlopen(request, timeout=timeout_s) as response:
                payload = response.read()
                response_type = response.headers.get("Content-Type", "application/octet-stream")
                content_disposition = response.headers.get("Content-Disposition", "")
                status = HTTPStatus(response.status)
        except Exception as exc:
            payload = json.dumps({"ok": False, "error": str(exc)}, ensure_ascii=False).encode("utf-8")
            response_type = "application/json; charset=utf-8"
            content_disposition = ""
            status = HTTPStatus.BAD_GATEWAY
        self.send_response(status)
        self.send_header("Content-Type", response_type)
        if content_disposition:
            self.send_header("Content-Disposition", content_disposition)
        self.send_header("Cache-Control", "no-store")
        self.send_header("Content-Length", str(len(payload)))
        self.end_headers()
        if send_body:
            self.wfile.write(payload)

    def _send_portal_oscilloscope(self, send_body: bool) -> None:
        if self._require_portal_session() is None:
            return
        try:
            with urlopen(f"{CORE_SERVICE_URL}/", timeout=4.0) as response:
                payload = self._rewrite_core_html_for_portal(response.read())
        except Exception as exc:
            payload = (
                "<!doctype html><html><head><meta charset=\"utf-8\">"
                "<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">"
                "<title>BMI30 Oscilloscope</title></head><body>"
                "<h1>BMI30 Oscilloscope</h1>"
                f"<p>Unable to contact BMI30 core service: {html.escape(str(exc))}</p>"
                "</body></html>"
            ).encode("utf-8")
        self.send_response(HTTPStatus.OK)
        self.send_header("Content-Type", "text/html; charset=utf-8")
        self.send_header("Permissions-Policy", "microphone=(self)")
        self.send_header("Cache-Control", "no-store, no-cache, must-revalidate, max-age=0")
        self.send_header("Content-Length", str(len(payload)))
        self.end_headers()
        if send_body:
            self.wfile.write(payload)

    def _handle_request(self, send_body: bool) -> None:
        path = self.path.split("?", 1)[0]
        if path in ("/portal-wifi-profiles", "/api/wifi-profiles"):
            if path == "/portal-wifi-profiles":
                if self._require_portal_session() is None: return
            elif self._get_portal_session() is None:
                self._send_json_response({"ok": False, "error": "Not authorized."}, 403, send_body=send_body)
                return
            try:
                if path == "/api/wifi-profiles":
                    self._send_json_response(bmi30_wifi_profiles_module().dispatch('list'), send_body=send_body)
                else:
                    payload = (bmi30_usb_module().MODULE / 'wifi_profiles.html').read_bytes()
                    self.send_response(200)
                    self.send_header('Content-Type', 'text/html; charset=utf-8')
                    self.send_header('Cache-Control', 'no-store')
                    self.send_header('Content-Length', str(len(payload)))
                    self.end_headers()
                    if send_body: self.wfile.write(payload)
            except Exception:
                self._send_json_response({"ok": False, "error": "Saved networks are temporarily unavailable."}, 503, send_body=send_body)
            return

        if path == "/api/firmware-check.js":
            if self._get_portal_session() is None:
                self._send_json_response({"ok": False, "error": "Not authorized."}, 403, send_body=send_body)
                return
            payload = (bmi30_usb_module().MODULE / "firmware_check.js").read_bytes()
            self.send_response(200)
            self.send_header("Content-Type", "application/javascript; charset=utf-8")
            self.send_header("Cache-Control", "no-store")
            self.send_header("Content-Length", str(len(payload)))
            self.end_headers()
            if send_body: self.wfile.write(payload)
            return

        if path == "/portal-recovery" or path == "/api/usb-recovery/status":
            if path == "/portal-recovery":
                if self._require_portal_session() is None:
                    return
            elif self._get_portal_session() is None:
                self._send_json_response({"ok": False, "error": "Not authorized."}, 403, send_body=send_body)
                return
            try:
                module = bmi30_usb_module()
                if path.endswith('/status'):
                    self._send_json_response(module.dispatch('status'), send_body=send_body)
                else:
                    payload = (module.MODULE / 'recovery.html').read_bytes()
                    self.send_response(200)
                    self.send_header('Content-Type', 'text/html; charset=utf-8')
                    self.send_header('Cache-Control', 'no-store')
                    self.send_header('Content-Length', str(len(payload)))
                    self.end_headers()
                    if send_body: self.wfile.write(payload)
            except Exception:
                self._send_json_response({"ok": False, "error": "Восстановление временно недоступно."}, 503, send_body=send_body)
            return

        preferred_ip = extract_request_host_ip(self.headers.get("Host", ""))

        # Legacy Android CNA endpoint: return 204 so the popup can close cleanly.
        if path == "/portal-done":
            self.send_response(HTTPStatus.NO_CONTENT)
            self.send_header("Cache-Control", "no-store")
            self.end_headers()
            return

        if path in {"/bmi30-ca.crt", "/bmi30-ca.pem"}:
            try:
                with open(TLS_CA_CERT_PATH, "rb") as handle:
                    payload = handle.read(128 * 1024)
                if not payload or b"BEGIN CERTIFICATE" not in payload:
                    raise ValueError("invalid CA certificate")
            except Exception:
                self.send_response(HTTPStatus.NOT_FOUND)
                self.send_header("Cache-Control", "no-store")
                self.end_headers()
                return
            self.send_response(HTTPStatus.OK)
            self.send_header("Content-Type", "application/x-x509-ca-cert")
            self.send_header("Content-Disposition", 'attachment; filename="BMI30-Local-CA.crt"')
            self.send_header("Cache-Control", "no-store")
            self.send_header("Content-Length", str(len(payload)))
            self.end_headers()
            if send_body:
                self.wfile.write(payload)
            return

        if path == "/favicon.ico":
            icon = load_logo_bytes(detect_logo_path(FAVICON_ICO_CANDIDATES))
            if icon is None:
                self.send_response(HTTPStatus.NOT_FOUND)
                self.end_headers()
                return
            payload, ctype = icon
            self.send_response(HTTPStatus.OK)
            self.send_header("Content-Type", ctype)
            self.send_header("Cache-Control", "no-store")
            self.send_header("Content-Length", str(len(payload)))
            self.end_headers()
            if send_body:
                self.wfile.write(payload)
            return

        if path == "/favicon.png":
            icon = load_logo_bytes(detect_logo_path(FAVICON_PNG_CANDIDATES))
            if icon is None:
                self.send_response(HTTPStatus.NOT_FOUND)
                self.end_headers()
                return
            payload, ctype = icon
            self.send_response(HTTPStatus.OK)
            self.send_header("Content-Type", ctype)
            self.send_header("Cache-Control", "no-store")
            self.send_header("Content-Length", str(len(payload)))
            self.end_headers()
            if send_body:
                self.wfile.write(payload)
            return

        if path == "/logo-tagit":
            logo = load_logo_bytes(detect_logo_path(TAGIT_LOGO_CANDIDATES))
            if logo is None:
                self.send_response(HTTPStatus.NOT_FOUND)
                self.end_headers()
                return
            payload, ctype = logo
            self.send_response(HTTPStatus.OK)
            self.send_header("Content-Type", ctype)
            self.send_header("Cache-Control", "no-store")
            self.send_header("Content-Length", str(len(payload)))
            self.end_headers()
            if send_body:
                self.wfile.write(payload)
            return

        if path in {"/logo-am", "/logo"}:
            logo = load_logo_bytes(detect_logo_path(AM_LOGO_CANDIDATES))
            if logo is None:
                self.send_response(HTTPStatus.NOT_FOUND)
                self.end_headers()
                return
            payload, ctype = logo
            self.send_response(HTTPStatus.OK)
            self.send_header("Content-Type", ctype)
            self.send_header("Cache-Control", "no-store")
            self.send_header("Content-Length", str(len(payload)))
            self.end_headers()
            if send_body:
                self.wfile.write(payload)
            return

        if path == "/portal-oscilloscope":
            self._send_portal_oscilloscope(send_body)
            return

        if path.startswith("/portal-core/") or path == "/portal-core":
            if self._require_portal_session() is None:
                return
            self._proxy_core_request(send_body, method="GET")
            return

        if path == "/api/bluetooth/remote-test/events":
            bmi30_bluetooth_remote_request(self, "events", send_body=send_body)
            return

        # JSON API
        if path == "/api/bluetooth-microphone-meter":
            if self._get_portal_session() is None:
                self._send_json_response(
                    {"ok": False, "error": "Not authorized."},
                    HTTPStatus.FORBIDDEN,
                    send_body=send_body,
                )
                return
            remember_portal_client(self.client_address[0] if self.client_address else "")
            meter = _bluetooth_microphone_meter_snapshot(refresh_lease=True)
            self._send_json_response({"ok": True, "meter": meter}, send_body=send_body)
            return

        if path == "/api/bluetooth-audio-status":
            if self._get_portal_session() is None:
                self._send_json_response(
                    {"ok": False, "error": "Not authorized."},
                    HTTPStatus.FORBIDDEN,
                    send_body=send_body,
                )
                return
            remember_portal_client(self.client_address[0] if self.client_address else "")
            self._send_json_response(collect_bluetooth_audio_status(), send_body=send_body)
            return

        if path == "/api/firmware-control":
            if self._get_portal_session() is None:
                self._send_json_response(
                    {"ok": False, "error": "Not authorized."},
                    HTTPStatus.FORBIDDEN,
                    send_body=send_body,
                )
                return
            self._send_json_response(firmware_control_public_state(), send_body=send_body)
            return

        if path == "/bmi30-connect.cmd":
            payload = pathlib.Path('/opt/bmi30-network/Open-BMI30.cmd').read_bytes()
            self.send_response(200)
            self.send_header('Content-Type', 'application/octet-stream')
            self.send_header('Content-Disposition', 'attachment; filename="Open-BMI30.cmd"')
            self.send_header('Content-Length', str(len(payload)))
            self.end_headers()
            if send_body: self.wfile.write(payload)
            return

        if path in {"/api/access/status", "/api/access/qr"}:
            if self._get_portal_session() is None:
                self._send_json_response({"ok": False, "error": "Not authorized."}, 403, send_body=send_body)
                return
            try:
                if path.endswith('/qr'):
                    kind = parse_qs(urlsplit(self.path).query).get('kind', ['portal'])[0]
                    payload = bmi30_access_qr(kind)
                    self.send_response(200)
                    self.send_header('Content-Type', 'image/svg+xml')
                    self.send_header('Cache-Control', 'no-store')
                    self.send_header('Content-Length', str(len(payload)))
                    self.end_headers()
                    if send_body: self.wfile.write(payload)
                else:
                    self._send_json_response(bmi30_access_call('/status'), send_body=send_body)
            except Exception:
                self._send_json_response({"ok": False, "error": "Служба связи недоступна. Попробуйте ещё раз."}, 503, send_body=send_body)
            return

        if path == "/api/status":
            if self._get_portal_session() is not None:
                remember_portal_client(self.client_address[0] if self.client_address else "")
            data = collect_remote_access_targets(preferred_ip=preferred_ip)
            data["service_recovery"] = read_legacy_service_recovery_diagnostics()
            payload = json.dumps(data, ensure_ascii=False, indent=2).encode("utf-8")
            self.send_response(HTTPStatus.OK)
            self.send_header("Content-Type", "application/json; charset=utf-8")
            self.send_header("Cache-Control", "no-store, no-cache, must-revalidate, max-age=0")
            firmware = data.get("firmware_release") if isinstance(data.get("firmware_release"), dict) else {}
            self.send_header("X-BMI30-Firmware-Version", str(firmware.get("version") or "unknown"))
            self.send_header("X-BMI30-Portal-SHA256", str(firmware.get("runtime_portal_sha256") or "unknown"))
            self.send_header("Content-Length", str(len(payload)))
            self.end_headers()
            if send_body:
                self.wfile.write(payload)
            return

        if path == "/api/scope/live":
            if not send_body:
                self.send_error(HTTPStatus.METHOD_NOT_ALLOWED)
                return
            try:
                import sys
                if "/opt/bmi30-network" not in sys.path:
                    sys.path.insert(0, "/opt/bmi30-network")
                from scope_live import serve_scope
                serve_scope(self)
            except ImportError:
                self.send_error(HTTPStatus.SERVICE_UNAVAILABLE)
            return

        if path == "/api/group/live":
            if not send_body:
                self.send_error(HTTPStatus.METHOD_NOT_ALLOWED)
                return
            try:
                import sys
                if "/opt/bmi30-network" not in sys.path:
                    sys.path.insert(0, "/opt/bmi30-network")
                from realtime import serve_portal
                serve_portal(self)
            except ImportError:
                self.send_error(HTTPStatus.SERVICE_UNAVAILABLE)
            return

        if path == "/api/sensors":
            session = self._get_portal_session()
            if session is None:
                self.send_response(HTTPStatus.FORBIDDEN)
                self.send_header("Content-Length", "0")
                self.end_headers()
                return
            rpi_temps = _read_rpi_temperatures()
            rpi_data = {lbl.lower(): round(t, 1) for lbl, t in rpi_temps}
            rpi_hwmon = _read_rpi_hwmon_readings()
            device_cache = _read_device_state_cache()
            stm32_temp = _device_cache_temperature(device_cache)
            device_sensors = _device_cache_sensors(device_cache)
            core_status = _read_core_status_snapshot()
            core_sync = core_status.get("sync") if isinstance(core_status.get("sync"), dict) else {}
            if core_sync:
                device_sensors["sync"] = dict(core_sync)
                events = device_sensors.get("events") if isinstance(device_sensors.get("events"), dict) else {}
                sync_state = events.get("sync_state") if isinstance(events.get("sync_state"), dict) else {}
                events["sync_state"] = {**sync_state, **core_sync}
                device_sensors["events"] = events
            device_sensors["bmi30_network"] = read_bmi30_group_file("status.json", 60)
            device_sensors["bmi30_group"] = read_bmi30_group_file("group.json", 2)
            device_sensors["optic_settings"] = _read_core_optic_settings()
            device_sensors["lan_devices"] = _current_group_lan_devices(
                get_lan_bmi30_devices(),
                device_sensors,
            )
            with _LAN_DEVICE_LOCK:
                device_sensors["lan_devices_updated_at"] = float(_LAN_DEVICE_CACHE.get("updated_at", 0.0) or 0.0)
                device_sensors["lan_sensors_updated_at"] = float(_LAN_DEVICE_CACHE.get("sensor_updated_at", 0.0) or 0.0)
            sensors_data: dict = {
                "rpi": rpi_data,
                "rpi_hwmon": rpi_hwmon,
                "stm32": round(stm32_temp, 1) if isinstance(stm32_temp, (int, float)) else None,
                "host": group_local_host_identity(preferred_ip=preferred_ip),
                "device": device_sensors,
            }
            payload = json.dumps(sensors_data, ensure_ascii=False).encode("utf-8")
            self.send_response(HTTPStatus.OK)
            self.send_header("Content-Type", "application/json; charset=utf-8")
            self.send_header("Cache-Control", "no-store")
            self.send_header("Content-Length", str(len(payload)))
            self.end_headers()
            if send_body:
                self.wfile.write(payload)
            return

        if path == "/portal-logout":
            self._send_redirect(
                self._absolute_url(with_rev("/login"), scheme=self._preferred_scheme()),
                status=HTTPStatus.SEE_OTHER,
                set_cookie=build_expired_portal_session_cookie(secure=self._is_tls()),
            )
            return

        if path == "/portal":
            session = self._get_portal_session()
            if session is None:
                self._send_redirect(
                    self._absolute_url(with_rev("/login"), scheme=self._preferred_scheme()),
                    set_cookie=build_expired_portal_session_cookie(secure=self._is_tls()),
                )
                return
            remember_portal_client(self.client_address[0] if self.client_address else "")
            data = collect_remote_access_targets(preferred_ip=preferred_ip)
            query = parse_qs(self.path.split("?", 1)[1] if "?" in self.path else "")
            notice = ""
            notice_kind = "ok"
            if query.get("saved", [""])[0] == "1":
                notice = "DC configuration saved."
            if query.get("applied", [""])[0] == "1":
                notice = "DC configuration saved and sent to the device."
            if query.get("error", [""])[0] == "1":
                notice = "DC configuration saved, but the device did not accept the live apply. Check USB connection and try again."
                notice_kind = "error"
            if query.get("tag_saved", [""])[0] == "1":
                notice = "Tag Detection settings saved."
            if query.get("tag_applied", [""])[0] == "1":
                notice = "Tag Detection settings saved and sent to BMI30 core."
            if query.get("tag_error", [""])[0] == "1":
                notice = "Tag Detection settings saved, but BMI30 core did not accept the live apply. Check core service and try again."
                notice_kind = "error"
            if query.get("group_applied", [""])[0] == "1":
                notice = "Optic settings saved and sent to BMI30 core."
            if query.get("group_error", [""])[0] == "1":
                notice = "Optic settings could not be applied. Check the BMI30 core service and USB connection."
                notice_kind = "error"
            if query.get("operation_saved", [""])[0] == "1":
                notice = "Operating mode, sound, and DC adaptation timing saved."
            if query.get("operation_applied", [""])[0] == "1":
                notice = "Operating mode, sound, and DC adaptation timing saved and sent to BMI30 core."
            if query.get("operation_error", [""])[0] == "1":
                notice = query.get(
                    "message",
                    ["Operating mode settings saved, but BMI30 core did not accept the live apply. Check core service and try again."],
                )[0][:240]
                notice_kind = "error"
            if query.get("account", [""])[0] == "1":
                notice = "Portal login and password saved."
            if query.get("hotspot", [""])[0] == "1":
                notice = "HotSpot Wi-Fi access settings saved."
            if query.get("wifi", [""])[0] == "1":
                notice = "Wi-Fi internet access saved."
            if query.get("engineer", [""])[0] == "1":
                notice = "BMI30 portal engineer login saved."
            if query.get("remote", [""])[0] == "1":
                notice = "Remote desktop RDP/VNC login saved."
            if query.get("channel", [""])[0] == "1":
                notice = "Communication channel permission saved."
            if query.get("privacy_error", [""])[0] == "1":
                notice = query.get("message", ["Unable to save privacy settings."])[0][:240]
                notice_kind = "error"
            payload = render_portal_page(
                data["hostname"],
                session_username=str(session.get("u", "")),
                session_role=str(session.get("r", "user")),
                notice=notice,
                notice_kind=notice_kind,
                request_host=self.headers.get("Host", ""),
            )
            self.send_response(HTTPStatus.OK)
            self.send_header("Content-Type", "text/html; charset=utf-8")
            self.send_header("Cache-Control", "no-store, no-cache, must-revalidate, max-age=0")
            self.send_header("Content-Length", str(len(payload)))
            self.end_headers()
            if send_body:
                self.wfile.write(payload)
            return

        # PDF для портала
        if path == "/portal-pdf":
            session = self._get_portal_session()
            if session is None:
                self.send_response(HTTPStatus.UNAUTHORIZED)
                self.send_header("Content-Type", "text/plain; charset=utf-8")
                self.end_headers()
                if send_body:
                    self.wfile.write(b"Not authorized")
                return
            query = parse_qs(self.path.split("?", 1)[1] if "?" in self.path else "")
            doc_key = query.get("doc", [""])[0].strip().lower()
            doc = PORTAL_DOCUMENTS.get(doc_key)
            if doc is None:
                self.send_response(HTTPStatus.NOT_FOUND)
                self.end_headers()
                if send_body:
                    self.wfile.write(b"PDF not found")
                return
            
            google_doc_id = doc.get("google_doc_id", "").strip()
            if not google_doc_id:
                self.send_response(HTTPStatus.NOT_FOUND)
                self.end_headers()
                return
            
            pdf_data = get_pdf_data(google_doc_id)
            if pdf_data is None:
                self.send_response(HTTPStatus.NOT_FOUND)
                self.send_header("Content-Type", "text/plain")
                self.end_headers()
                if send_body:
                    self.wfile.write(b"PDF temporarily unavailable")
                return
            
            self.send_response(HTTPStatus.OK)
            self.send_header("Content-Type", "application/pdf")
            self.send_header("Cache-Control", "max-age=3600, public")
            self.send_header("Content-Length", str(len(pdf_data)))
            self.end_headers()
            if send_body:
                self.wfile.write(pdf_data)
            return

        if path == "/portal-pdf-update-check":
            session = self._get_portal_session()
            if session is None:
                self.send_response(HTTPStatus.UNAUTHORIZED)
                self.send_header("Content-Type", "application/json; charset=utf-8")
                self.end_headers()
                if send_body:
                    self.wfile.write(b'{"error":"not authorized"}')
                return

            query = parse_qs(self.path.split("?", 1)[1] if "?" in self.path else "")
            doc_key = query.get("doc", [""])[0].strip().lower()
            doc = PORTAL_DOCUMENTS.get(doc_key)
            if doc is None:
                self.send_response(HTTPStatus.NOT_FOUND)
                self.send_header("Content-Type", "application/json; charset=utf-8")
                self.end_headers()
                if send_body:
                    self.wfile.write(b'{"error":"doc not found"}')
                return

            google_doc_id = doc.get("google_doc_id", "").strip()
            cache_path = PDF_CACHE_DIR / f"{google_doc_id}.pdf"
            cached = _read_cached_pdf(cache_path)

            if cached is None:
                payload = json.dumps({"updateAvailable": True, "hasCache": False}, ensure_ascii=False).encode("utf-8")
                self.send_response(HTTPStatus.OK)
                self.send_header("Content-Type", "application/json; charset=utf-8")
                self.send_header("Cache-Control", "no-store")
                self.send_header("Content-Length", str(len(payload)))
                self.end_headers()
                if send_body:
                    self.wfile.write(payload)
                return

            remote = _fetch_google_doc_pdf_bytes(google_doc_id, timeout=12)
            update_available = False
            online = remote is not None
            if remote is not None:
                update_available = hashlib.sha256(remote).digest() != hashlib.sha256(cached).digest()

            payload = json.dumps(
                {"updateAvailable": update_available, "hasCache": True, "online": online},
                ensure_ascii=False,
            ).encode("utf-8")
            self.send_response(HTTPStatus.OK)
            self.send_header("Content-Type", "application/json; charset=utf-8")
            self.send_header("Cache-Control", "no-store")
            self.send_header("Content-Length", str(len(payload)))
            self.end_headers()
            if send_body:
                self.wfile.write(payload)
            return

        if path == "/portal-pdf-refresh":
            session = self._get_portal_session()
            if session is None:
                self.send_response(HTTPStatus.UNAUTHORIZED)
                self.send_header("Content-Type", "application/json; charset=utf-8")
                self.end_headers()
                if send_body:
                    self.wfile.write(b'{"error":"not authorized"}')
                return

            query = parse_qs(self.path.split("?", 1)[1] if "?" in self.path else "")
            doc_key = query.get("doc", [""])[0].strip().lower()
            doc = PORTAL_DOCUMENTS.get(doc_key)
            if doc is None:
                self.send_response(HTTPStatus.NOT_FOUND)
                self.send_header("Content-Type", "application/json; charset=utf-8")
                self.end_headers()
                if send_body:
                    self.wfile.write(b'{"error":"doc not found"}')
                return

            google_doc_id = doc.get("google_doc_id", "").strip()
            cache_path = PDF_CACHE_DIR / f"{google_doc_id}.pdf"
            previous = _read_cached_pdf(cache_path)
            remote = _fetch_google_doc_pdf_bytes(google_doc_id, timeout=20)
            if remote is None:
                self.send_response(HTTPStatus.BAD_GATEWAY)
                payload = json.dumps({"ok": False, "error": "remote unavailable"}, ensure_ascii=False).encode("utf-8")
                self.send_header("Content-Type", "application/json; charset=utf-8")
                self.send_header("Cache-Control", "no-store")
                self.send_header("Content-Length", str(len(payload)))
                self.end_headers()
                if send_body:
                    self.wfile.write(payload)
                return

            try:
                cache_path.parent.mkdir(parents=True, exist_ok=True)
                cache_path.write_bytes(remote)
                changed = previous is None or hashlib.sha256(previous).digest() != hashlib.sha256(remote).digest()
                payload = json.dumps({"ok": True, "updated": changed}, ensure_ascii=False).encode("utf-8")
                self.send_response(HTTPStatus.OK)
                self.send_header("Content-Type", "application/json; charset=utf-8")
                self.send_header("Cache-Control", "no-store")
                self.send_header("Content-Length", str(len(payload)))
                self.end_headers()
                if send_body:
                    self.wfile.write(payload)
                return
            except Exception:
                self.send_response(HTTPStatus.INTERNAL_SERVER_ERROR)
                payload = json.dumps({"ok": False, "error": "cache write failed"}, ensure_ascii=False).encode("utf-8")
                self.send_header("Content-Type", "application/json; charset=utf-8")
                self.send_header("Cache-Control", "no-store")
                self.send_header("Content-Length", str(len(payload)))
                self.end_headers()
                if send_body:
                    self.wfile.write(payload)
                return

        if path == "/portal-doc-download":
            session = self._get_portal_session()
            if session is None:
                self._send_redirect(
                    self._absolute_url(with_rev("/login"), scheme=self._preferred_scheme()),
                    set_cookie=build_expired_portal_session_cookie(secure=self._is_tls()),
                )
                return
            query = parse_qs(self.path.split("?", 1)[1] if "?" in self.path else "")
            doc_key = query.get("doc", [""])[0].strip().lower()
            doc = PORTAL_DOCUMENTS.get(doc_key)
            if doc is None:
                self.send_response(HTTPStatus.NOT_FOUND)
                self.send_header("Content-Type", "text/plain; charset=utf-8")
                self.send_header("Cache-Control", "no-store")
                self.end_headers()
                if send_body:
                    self.wfile.write(b"Documentation file not found.")
                return
            
            # Теперь скачиваем PDF вместо текста
            google_doc_id = doc.get("google_doc_id", "").strip()
            if not google_doc_id:
                self.send_response(HTTPStatus.NOT_FOUND)
                self.send_header("Content-Type", "text/plain")
                self.end_headers()
                if send_body:
                    self.wfile.write(b"PDF not configured")
                return
            
            pdf_data = get_pdf_data(google_doc_id)
            if pdf_data is None:
                self.send_response(HTTPStatus.NOT_FOUND)
                self.send_header("Content-Type", "text/plain")
                self.end_headers()
                if send_body:
                    self.wfile.write(b"PDF temporarily unavailable")
                return
            
            self.send_response(HTTPStatus.OK)
            self.send_header("Content-Type", "application/pdf")
            self.send_header("Cache-Control", "no-store")
            self.send_header("Content-Disposition", f'attachment; filename="{doc["filename"]}"')
            self.send_header("Content-Length", str(len(pdf_data)))
            self.end_headers()
            if send_body:
                self.wfile.write(pdf_data)
            return

        # Connectivity-probe.
        # Android/Chrome OS надёжнее открывают captive portal после 302 redirect
        # на страницу логина. Для Apple/Windows/Linux оставляем HTML прямо на probe URL.
        if path in ANDROID_PROBE_PATHS:
            login_url = self._absolute_url(with_rev("/login"), scheme=self._preferred_scheme())
            self.send_response(HTTPStatus.FOUND)
            self.send_header("Location", login_url)
            self.send_header("Cache-Control", "no-store, no-cache, must-revalidate, max-age=0")
            self.end_headers()
            return

        if path in PROBE_PATHS:
            data = collect_remote_access_targets(preferred_ip=preferred_ip)
            payload = render_html_page(data)
            self.send_response(HTTPStatus.OK)
            self.send_header("Content-Type", "text/html; charset=utf-8")
            self.send_header("Cache-Control", "no-store, no-cache, must-revalidate, max-age=0")
            self.send_header("Content-Length", str(len(payload)))
            self.end_headers()
            if send_body:
                self.wfile.write(payload)
            return

        # Информационная страница
        if path in INFO_PATHS:
            if is_https_enabled() and FORCE_HTTPS and not self._is_tls():
                self.send_response(HTTPStatus.FOUND)
                self.send_header("Location", self._absolute_url(path, scheme="https"))
                self.send_header("Cache-Control", "no-store")
                self.end_headers()
                return
            data = collect_remote_access_targets(preferred_ip=preferred_ip)
            payload = render_html_page(data)
            self.send_response(HTTPStatus.OK)
            self.send_header("Content-Type", "text/html; charset=utf-8")
            self.send_header("Cache-Control", "no-store, no-cache, must-revalidate, max-age=0")
            self.send_header("Content-Length", str(len(payload)))
            self.end_headers()
            if send_body:
                self.wfile.write(payload)
            return

        # Всё остальное — редирект на страницу входа
        self._send_redirect(self._absolute_url(with_rev("/login"), scheme=self._preferred_scheme()))

    def do_GET(self) -> None:
        self._handle_request(send_body=True)

    def do_HEAD(self) -> None:
        self._handle_request(send_body=False)

    def do_POST(self) -> None:
        path = self.path.split("?", 1)[0]
        if path in ("/api/bluetooth/remote-test/start", "/api/bluetooth/remote-test/stop"):
            bmi30_bluetooth_remote_request(self, path.rsplit("/", 1)[-1])
            return

        if path == "/api/wifi-profiles/password":
            if (self._get_portal_session() is None or self.headers.get('X-BMI30-WIFI') != '1'
                    or not bmi30_usb_origin_allowed(self)):
                self._send_json_response({"ok": False, "error": "Not authorized."}, 403)
                return
            try:
                size = int(self.headers.get('Content-Length', '0'))
                if not 0 < size <= 4096: raise ValueError()
                data = json.loads(self.rfile.read(size))
                if not isinstance(data, dict): raise ValueError()
                self._send_json_response(bmi30_wifi_profiles_module().dispatch('password', data))
            except Exception:
                self._send_json_response({"ok": False, "error": "The saved password could not be read."}, 409)
            return

        if path == "/api/firmware-check":
            if self._get_portal_session() is None or self.headers.get("X-BMI30-Firmware-Check") != "1":
                self._send_json_response({"ok": False, "error": "Not authorized."}, 403)
                return
            self._read_raw_post_body()
            result, status = request_manual_firmware_check()
            self._send_json_response(result, status)
            return

        if path in ("/api/usb-recovery/plan", "/api/usb-recovery/start", "/api/usb-recovery/read-stm32", "/api/usb-recovery/enable-emmc"):
            origin = self.headers.get('Origin', '')
            if (self._get_portal_session() is None or self.headers.get('X-BMI30-USB') != '1'
                    or (not bmi30_usb_origin_allowed(self))):
                self._send_json_response({"ok": False, "error": "Not authorized."}, 403)
                return
            try:
                size = int(self.headers.get('Content-Length', '0'))
                if not 0 < size <= 4096: raise ValueError('Invalid request size')
                data = json.loads(self.rfile.read(size))
                if not isinstance(data, dict): raise ValueError('Invalid request')
                response = bmi30_usb_module().dispatch(path.rsplit('/', 1)[-1], data)
                self._send_json_response(response, 202 if path.endswith('/start') else 200)
            except Exception as error:
                module = bmi30_usb_module()
                message = str(error) if isinstance(error, module.Refused) else 'Действие не выполнено. Обновите список USB.'
                self._send_json_response({"ok": False, "error": message}, 409)
            return

        if path == "/api/access/action":
            origin = self.headers.get('Origin', '')
            if (self._get_portal_session() is None or self.headers.get('X-BMI30-Access') != '1'
                    or (origin and urlsplit(origin).netloc != self.headers.get('Host', ''))):
                self._send_json_response({"ok": False, "error": "Not authorized."}, 403)
                return
            try:
                size = int(self.headers.get('Content-Length', '0'))
                if not 0 < size <= 4096: raise ValueError('Invalid size')
                data = json.loads(self.rfile.read(size))
                if not isinstance(data, dict): raise ValueError('Invalid request')
                response = bmi30_access_call('/action', data)
                self._send_json_response(response, 202)
            except Exception:
                self._send_json_response({"ok": False, "error": "Действие не выполнено. Проверьте выбор сети и повторите."}, 409)
            return


        if path in ("/api/scope/offer", "/api/scope/lease"):
            try:
                import sys
                if "/opt/bmi30-network" not in sys.path:
                    sys.path.insert(0, "/opt/bmi30-network")
                from scope_rtc_proxy import signaling
                signaling(self, path.rsplit("/", 1)[-1])
            except ImportError:
                self._send_json_response({"ok": False, "error": "Display transport unavailable"}, 503)
            return

        if path == "/api/bluetooth-microphone-meter":
            if self._get_portal_session() is None:
                self._send_json_response(
                    {"ok": False, "error": "Not authorized."},
                    HTTPStatus.FORBIDDEN,
                )
                return
            try:
                content_length = int(self.headers.get("Content-Length", "0") or "0")
            except ValueError:
                content_length = 0
            if content_length < 0 or content_length > 4096:
                self.close_connection = True
                self._send_json_response(
                    {"ok": False, "error": "Microphone-meter request is too large."},
                    HTTPStatus.REQUEST_ENTITY_TOO_LARGE,
                )
                return
            raw_body = self.rfile.read(content_length) if content_length else b"{}"
            try:
                body = json.loads(raw_body.decode("utf-8") or "{}")
            except Exception:
                body = {}
            if not isinstance(body, dict):
                body = {}
            action = str(body.get("action") or "start").strip().lower()
            address = str(body.get("address") or "").strip().upper()
            if action == "stop":
                meter = _stop_bluetooth_microphone_meter()
                ok, message = True, "Raspberry microphone meter stopped."
            elif action == "start":
                ok, message, meter = _start_bluetooth_microphone_meter(address)
            else:
                ok, message, meter = False, "Unsupported microphone-meter action.", _bluetooth_microphone_meter_snapshot()
            self._send_json_response(
                {"ok": bool(ok), "action": action, "address": address, "message": message, "meter": meter},
                HTTPStatus.OK if ok else HTTPStatus.CONFLICT,
            )
            return

        if path == "/api/bluetooth-audio-action":
            if self._get_portal_session() is None:
                self._send_json_response(
                    {"ok": False, "error": "Not authorized."},
                    HTTPStatus.FORBIDDEN,
                )
                return
            try:
                content_length = int(self.headers.get("Content-Length", "0") or "0")
            except ValueError:
                content_length = 0
            if content_length < 0 or content_length > 4096:
                self.close_connection = True
                self._send_json_response(
                    {"ok": False, "error": "Bluetooth request is too large."},
                    HTTPStatus.REQUEST_ENTITY_TOO_LARGE,
                )
                return
            raw_body = self.rfile.read(content_length) if content_length else b"{}"
            try:
                body = json.loads(raw_body.decode("utf-8") or "{}")
            except Exception:
                body = {}
            if not isinstance(body, dict):
                body = {}
            action = str(body.get("action") or "").strip().lower()
            address = str(body.get("address") or "").strip().upper()
            value = body.get("value")
            ok, message = apply_bluetooth_audio_action(action, address, value)
            message = _clean_process_text(message, 1200)
            response = {"ok": bool(ok), "action": action, "address": address, "message": message}
            try:
                response["status"] = collect_bluetooth_audio_status()
            except Exception:
                pass
            self._send_json_response(
                response,
                HTTPStatus.OK if ok else HTTPStatus.CONFLICT,
            )
            return

        if path in {"/api/firmware-update", "/api/firmware-rollback"}:
            if self._get_portal_session() is None:
                self._send_json_response(
                    {"ok": False, "error": "Not authorized."},
                    HTTPStatus.FORBIDDEN,
                )
                return
            self._read_raw_post_body()
            action = "update" if path.endswith("-update") else "rollback"
            ok, message = launch_firmware_operation(action)
            self._send_json_response(
                {"ok": ok, "action": action, "message": message},
                HTTPStatus.ACCEPTED if ok else HTTPStatus.CONFLICT,
            )
            return

        if path.startswith("/portal-core/") or path == "/portal-core":
            if self._require_portal_session() is None:
                return
            self._proxy_core_request(True, method="POST", body=self._read_raw_post_body())
            return

        if path == "/portal-account-config":
            session = self._get_portal_session()
            if session is None:
                self._send_redirect(
                    self._absolute_url(with_rev("/login"), scheme=self._preferred_scheme()),
                    status=HTTPStatus.SEE_OTHER,
                    set_cookie=build_expired_portal_session_cookie(secure=self._is_tls()),
                )
                return

            form = self._read_post_form()
